 9: 
10: class ShippingRateRequest extends FormRequest
11: {
12:     public function authorize(): bool
13:     {
14:         return true;
15:     }
16: 
17:     /** @return array<string, mixed> */
18:     public function rules(): array
19:     {
20:         $rate = $this->route('shipping_rate');
21: 
22:         return [
23:             'shipping_company_id' => ['required', 'integer', 'exists:shipping_companies,id'],
24:             'shipping_zone_id' => [
25:                 'required', 'integer', 'exists:shipping_zones,id',
26:                 Rule::unique('shipping_rates', 'shipping_zone_id')
27:                     ->where('shipping_company_id', $this->input('shipping_company_id'))
28:                     ->ignore($rate),
29:             ],
30:             'base_cost' => ['required', 'numeric', 'min:0'],
31:             'free_shipping_threshold' => ['nullable', 'numeric', 'min:0'],
32:             'cod_fee' => ['nullable', 'numeric', 'min:0'],
33:             'estimated_days_min' => ['required', 'integer', 'min:0'],
34:             'estimated_days_max' => ['required', 'integer', 'gte:estimated_days_min'],
