 5: namespace App\Models;
 6: 
 7: use Database\Factories\OrderItemFactory;
 8: use Illuminate\Database\Eloquent\Factories\HasFactory;
 9: use Illuminate\Database\Eloquent\Model;
10: use Illuminate\Database\Eloquent\Relations\BelongsTo;
11: 
12: class OrderItem extends Model
13: {
14:     /** @use HasFactory<OrderItemFactory> */
15:     use HasFactory;
16: 
17:     protected $fillable = [
18:         'order_id',
19:         'product_variant_id',
20:         'product_name_snapshot',
21:         'sku_snapshot',
22:         'allocated_branch_id',
23:         'qty',
24:         'unit_price',
25:         'discount_amount',
26:         'tax_amount',
27:         'line_total',
28:     ];
29: 
30:     protected function casts(): array
31:     {
32:         return [
33:             'qty' => 'decimal:4',
34:             'unit_price' => 'decimal:2',
35:             'discount_amount' => 'decimal:2',
36:             'tax_amount' => 'decimal:2',
37:             'line_total' => 'decimal:2',
38:         ];
39:     }
40: 
41:     /** @return BelongsTo<Order, $this> */
