126:     public function test_expire_pending_command_cancels_stale_orders_and_releases_stock(): void
127:     {
128:         $variant = $this->makeVariant();
129:         $this->giveStock($variant->id, 5);
130: 
131:         $makeOrder = function (string $method, int $ageHours) use ($variant): Order {
132:             $customer = Customer::factory()->create();
133:             $cart = Cart::factory()->for($customer)->create();
134:             $cart->items()->create(['product_variant_id' => $variant->id, 'qty' => 1]);
135:             $order = app(OrderService::class)->createFromCart($cart->fresh(), [
136:                 'payment_method' => $method, 'shipping_cost' => 0, 'city_id' => null,
137:                 'address_snapshot' => ['city' => 'القاهرة'],
138:             ], $customer);
139:             $order->forceFill(['created_at' => now()->subHours($ageHours)])->saveQuietly();
140: 
141:             return $order;
142:         };
143: 
144:         $staleCod = $makeOrder('cod', 100);       // أقدم من 72 ساعة
145:         $staleOnline = $makeOrder('card', 2);     // إلكتروني غير مدفوع أقدم من 30 دقيقة
146:         $freshCod = $makeOrder('cod', 1);         // حديث — يبقى
147: 
148:         Artisan::call('orders:expire-pending');
149: 
150:         $this->assertSame('cancelled', $staleCod->fresh()->status->value);
151:         $this->assertSame('cancelled', $staleOnline->fresh()->status->value);
152:         $this->assertSame('pending', $freshCod->fresh()->status->value);
153:         // حجوزات الملغاة رُفعت ويبقى حجز الطلب الحديث فقط
154:         $this->assertEquals(1, (float) StockLevel::where('product_variant_id', $variant->id)->first()->reserved);
155:     }
