 95:     private function shippedCodOrder(float $price = 100): array
 96:     {
 97:         $variant = $this->variant($price);
 98:         $this->giveStock($variant, 10);
 99:         $order = Order::findOrFail($this->guestCheckout($variant, 2)->assertCreated()->json('data.id'));
100:         $company = ShippingCompany::query()->firstOrCreate(
101:             ['code' => 'SHIPX'],
102:             ['name' => 'ShipX', 'is_active' => true, 'api_credentials' => ['webhook_secret' => 'ship-secret']],
103:         );
104:         $this->withToken($this->staffToken())->patchJson("/api/v1/admin/orders/{$order->id}/status", [
105:             'status' => 'confirmed',
106:         ])->assertOk();
107:         $this->withToken($this->staffToken())->postJson("/api/v1/admin/orders/{$order->id}/shipment", [
108:             'shipping_company_id' => $company->id,
109:         ])->assertOk();
110:         $order->refresh();
111:         $this->assertSame(OrderStatus::Shipped, $order->status);
112: 
113:         return [$order, $order->shipments()->firstOrFail(), $company];
114:     }
115: 
116:     private function shippingWebhook(Shipment $shipment, string $status, string $eventId): void
117:     {
118:         $body = json_encode([
119:             'event_id' => $eventId, 'awb_number' => $shipment->awb_number, 'status' => $status,
120:         ]);
121:         $this->call('POST', '/api/v1/webhooks/shipping/SHIPX', [], [], [],
122:             ['CONTENT_TYPE' => 'application/json', 'HTTP_X_WEBHOOK_SIGNATURE' => hash_hmac('sha256', $body, 'ship-secret')],
123:             $body)->assertOk();
124:     }
