 29: /**
 30:  * المرحلة 8.3: ويب هوكس الدفع والشحن — توقيع HMAC، تسجيل مسبق في
 31:  * webhook_logs، عدم تكرار المعالجة، وتأثيرات الطلب التلقائية.
 32:  */
 33: class WebhookTest extends TestCase
 34: {
 35:     use LazilyRefreshDatabase;
 36: 
 37:     private const PAY_SECRET = 'pay-secret';
 38: 
 39:     private const SHIP_SECRET = 'ship-secret';
 40: 
 41:     private User $staff;
 42: 
 43:     private Branch $branch;
 44: 
 45:     protected function setUp(): void
 46:     {
 47:         parent::setUp();
 48:         $this->seed(SettingSeeder::class);
 49:         config(['webhooks.payment.testpay' => [
 50:             'secret' => self::PAY_SECRET,
 51:             'signature_header' => 'X-Webhook-Signature',
 52:         ]]);
 53:         $this->staff = User::factory()->create();
 54:         // منفّذ نظام: تأكيد الويب هوك بلا فاعل موظف — يسقط على أول Super Admin
 55:         $superAdmin = User::factory()->create();
 56:         $superAdmin->assignRole(Role::findOrCreate('Super Admin', 'staff'));
 57:         $this->branch = Branch::factory()->create();
 58:     }
 59: 
 60:     public function test_payment_success_marks_paid_confirms_and_allocates(): void
 61:     {
 62:         $variant = $this->purchasableVariant(100);
 63:         $this->giveStock($variant, 10);
 64:         $order = $this->makeOrder($variant, 2, 'card');
 65:         $this->assertSame(OrderStatus::Pending, $order->status);
 66: 
 67:         $this->postWebhook('/api/v1/webhooks/payment/testpay', [
 68:             'event_id' => 'evt_1', 'order_number' => $order->order_number, 'status' => 'paid',
 69:         ], self::PAY_SECRET)->assertOk()->assertJsonPath('received', true);
 70: 
 71:         $order = $order->fresh();
 72:         $this->assertSame('paid', $order->payment_status);
 73:         $this->assertSame(OrderStatus::Confirmed, $order->status);
 74:         $this->assertSame($this->branch->id, $order->allocated_branch_id);
 75:         $this->assertSame('2.0000', (string) $this->level($variant->id)->reserved);
 76:         $this->assertSame('processed', WebhookLog::query()->sole()->status);
 77:         $this->assertTrue(WebhookLog::query()->sole()->signature_valid);
 78:     }
 79: 
 80:     public function test_payment_webhook_rejects_bad_signature_and_logs_it(): void
 81:     {
 82:         $variant = $this->purchasableVariant(100);
 83:         $this->giveStock($variant, 5);
 84:         $order = $this->makeOrder($variant, 1, 'card');
 85: 
 86:         $this->postWebhook('/api/v1/webhooks/payment/testpay', [
 87:             'event_id' => 'evt_bad', 'order_number' => $order->order_number, 'status' => 'paid',
 88:         ], 'wrong-secret')->assertForbidden();
 89: 
 90:         $order = $order->fresh();
 91:         $this->assertSame('unpaid', $order->payment_status); // دفع كارت يبدأ unpaid
 92:         $this->assertSame(OrderStatus::Pending, $order->status);
 93:         $this->assertSame('invalid_signature', WebhookLog::query()->sole()->status);
 94:     }
 95: 
 96:     public function test_payment_webhook_duplicate_event_is_not_reprocessed(): void
 97:     {
 98:         $variant = $this->purchasableVariant(100);
 99:         $this->giveStock($variant, 10);
100:         $order = $this->makeOrder($variant, 2, 'card');
101:         $payload = ['event_id' => 'evt_dup', 'order_number' => $order->order_number, 'status' => 'paid'];
102: 
103:         $this->postWebhook('/api/v1/webhooks/payment/testpay', $payload, self::PAY_SECRET)->assertOk();
104:         $histories = $order->statusHistories()->count();
105:         $movements = StockMovement::query()->where('type', StockMovementType::Reserve)->count();
106: 
107:         $this->postWebhook('/api/v1/webhooks/payment/testpay', $payload, self::PAY_SECRET)
108:             ->assertOk()->assertJsonPath('duplicate', true);
109: 
110:         $this->assertSame($histories, $order->statusHistories()->count());
111:         $this->assertSame($movements, StockMovement::query()->where('type', StockMovementType::Reserve)->count());
112:         $this->assertSame('2.0000', (string) $this->level($variant->id)->reserved);
113:         $this->assertSame('duplicate', WebhookLog::query()->latest('id')->first()->status);
114:     }
115: 
116:     public function test_payment_failed_keeps_order_pending_and_unknown_gateway_404(): void
117:     {
118:         $variant = $this->purchasableVariant(100);
119:         $this->giveStock($variant, 5);
120:         $order = $this->makeOrder($variant, 1, 'card');
121: 
122:         $this->postWebhook('/api/v1/webhooks/payment/testpay', [
123:             'event_id' => 'evt_fail', 'order_number' => $order->order_number, 'status' => 'failed',
124:         ], self::PAY_SECRET)->assertOk();
125: 
126:         $order = $order->fresh();
127:         $this->assertSame('failed', $order->payment_status);
128:         $this->assertSame(OrderStatus::Pending, $order->status);
129: 
130:         $this->postWebhook('/api/v1/webhooks/payment/nosuch', [
131:             'order_number' => $order->order_number, 'status' => 'paid',
132:         ], self::PAY_SECRET)->assertNotFound();
133:     }
134: 
135:     public function test_shipping_delivered_webhook_delivers_order_and_settles_cod(): void
136:     {
137:         $variant = $this->purchasableVariant(100);
138:         $this->giveStock($variant, 5);
139:         $order = $this->makeOrder($variant, 1, 'cod');
140:         app(OrderService::class)->changeStatus($order, OrderStatus::Confirmed, $this->staff);
141: 
142:         $company = ShippingCompany::factory()->create([
143:             'code' => 'bosta',
144:             'api_credentials' => ['webhook_secret' => self::SHIP_SECRET],
145:         ]);
146:         app(ShipmentService::class)->createForOrder($order, $company->id, 'BOSTA-123', $this->staff);
147:         $this->assertSame(OrderStatus::Shipped, $order->fresh()->status);
148: 
149:         $this->postWebhook('/api/v1/webhooks/shipping/bosta', [
150:             'event_id' => 'ev_ship_1', 'awb_number' => 'BOSTA-123', 'status' => 'delivered',
151:         ], self::SHIP_SECRET)->assertOk()->assertJsonPath('received', true);
152: 
153:         $order = $order->fresh();
154:         $this->assertSame(OrderStatus::Delivered, $order->status);
155:         $this->assertSame('paid', $order->payment_status); // COD يُحصّل عند التسليم
156:         $this->assertSame('delivered', $order->shipments()->sole()->status->value);
157:     }
158: 
159:     public function test_shipping_webhook_unknown_awb_and_bad_signature(): void
160:     {
161:         ShippingCompany::factory()->create([
162:             'code' => 'bosta',
163:             'api_credentials' => ['webhook_secret' => self::SHIP_SECRET],
164:         ]);
165: 
166:         $this->postWebhook('/api/v1/webhooks/shipping/bosta', [
167:             'event_id' => 'ev_x', 'awb_number' => 'NOPE-1', 'status' => 'in_transit',
168:         ], self::SHIP_SECRET)->assertOk()->assertJsonPath('received', false);
169:         $this->assertSame('failed', WebhookLog::query()->sole()->status);
170: 
171:         $this->postWebhook('/api/v1/webhooks/shipping/bosta', [
172:             'event_id' => 'ev_y', 'awb_number' => 'NOPE-1', 'status' => 'delivered',
173:         ], 'bad')->assertForbidden();
174:     }
175: 
176:     // ---------- helpers ----------
177: 
178:     private function postWebhook(string $uri, array $payload, string $secret): TestResponse
179:     {
180:         $body = json_encode($payload);
181: 
182:         return $this->call('POST', $uri, [], [], [], [
183:             'HTTP_X-Webhook-Signature' => hash_hmac('sha256', $body, $secret),
184:             'CONTENT_TYPE' => 'application/json',
185:             'HTTP_ACCEPT' => 'application/json',
186:         ], $body);
187:     }
188: 
189:     private function makeOrder(ProductVariant $variant, float|int $qty, string $paymentMethod): Order
190:     {
191:         $cart = Cart::create([]);
192:         $cart->items()->create(['product_variant_id' => $variant->id, 'qty' => $qty]);
193: 
194:         return app(OrderService::class)->createFromCart($cart, [
195:             'recipient_name' => 'عميل', 'recipient_phone' => '01012345678',
196:             'payment_method' => $paymentMethod,
197:         ]);
198:     }
199: 
200:     private function purchasableVariant(float $price): ProductVariant
201:     {
202:         $product = Product::factory()->create(['status' => 'published']);
203: 
204:         return ProductVariant::factory()->create([
205:             'product_id' => $product->id,
206:             'retail_price' => $price,
207:         ]);
208:     }
209: 
210:     private function giveStock(ProductVariant $variant, float|int $qty): void
211:     {
212:         app(InventoryService::class)->recordMovement([
213:             'product_variant_id' => $variant->id,
214:             'branch_id' => $this->branch->id,
215:             'type' => StockMovementType::AdjustmentIn,
216:             'affected_bucket' => StockBucket::OnHand,
217:             'quantity' => $qty,
218:             'created_by' => $this->staff->id,
219:         ]);
220:     }
221: 
222:     private function level(int $variantId): StockLevel
223:     {
224:         return StockLevel::query()
225:             ->where('product_variant_id', $variantId)
226:             ->where('branch_id', $this->branch->id)
227:             ->whereNull('location_id')
228:             ->firstOrFail();
229:     }
230: } 1: <?php
