 5: namespace App\Console\Commands;
 6: 
 7: use App\Models\WebhookLog;
 8: use Illuminate\Console\Command;
 9: 
10: /** حذف سجلات الويب هوك القديمة — سياسة احتفاظ بدل نمو بلا حد (M4). */
11: class PruneWebhookLogs extends Command
12: {
13:     protected $signature = 'webhooks:prune-logs {--days=90 : الاحتفاظ بعدد الأيام هذا}';
14: 
15:     protected $description = 'Delete webhook log rows older than the retention window';
16: 
17:     public function handle(): int
18:     {
19:         $days = max(1, (int) $this->option('days'));
20:         $cutoff = now()->subDays($days);
21:         $deleted = 0;
22: 
23:         // الحذف على دفعات (F-29): عبارة DELETE واحدة على جدول ضخم تُطيل
24:         // القفل وتفشل عند تراكم ملايين السجلات
25:         do {
26:             $batch = WebhookLog::query()
27:                 ->where('created_at', '<', $cutoff)
28:                 ->limit(1000)
29:                 ->delete();
30:             $deleted += $batch;
31:         } while ($batch > 0);
32: 
33:         $this->info("Pruned {$deleted} webhook log rows older than {$days} days.");
34: 
35:         return self::SUCCESS;
36:     }
37: } 1: <?php
