 7: use App\Exceptions\BusinessException;
 8: use App\Http\Controllers\Controller;
 9: use App\Http\Requests\Admin\Promotion\CouponRequest;
10: use App\Http\Resources\Admin\CouponResource;
11: use App\Models\Cart;
12: use App\Models\Coupon;
13: use Illuminate\Http\JsonResponse;
14: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
15: use Illuminate\Routing\Controllers\HasMiddleware;
16: use Illuminate\Routing\Controllers\Middleware;
17: 
18: /** إدارة كوبونات الخصم. */
19: class CouponController extends Controller implements HasMiddleware
20: {
21:     public static function middleware(): array
22:     {
23:         return [
24:             new Middleware('can:coupons.view', only: ['index', 'show']),
25:             new Middleware('can:coupons.create', only: ['store']),
26:             new Middleware('can:coupons.update', only: ['update']),
27:             new Middleware('can:coupons.delete', only: ['destroy']),
28:         ];
29:     }
30: 
31:     public function index(): AnonymousResourceCollection
32:     {
33:         return CouponResource::collection(Coupon::query()->latest('id')->paginate(20));
34:     }
35: 
36:     public function store(CouponRequest $request): JsonResponse
37:     {
38:         $data = $this->withoutNulls($request->validated());
39:         $data['value'] ??= 0;
40:         $data['usage_limit_per_customer'] ??= 1;
41:         $coupon = Coupon::create($data);
42: 
43:         return CouponResource::make($coupon)->response()->setStatusCode(201);
44:     }
45: 
46:     public function show(Coupon $coupon): CouponResource
47:     {
48:         return CouponResource::make($coupon);
49:     }
50: 
51:     public function update(CouponRequest $request, Coupon $coupon): CouponResource
52:     {
53:         $coupon->update($this->withoutNulls($request->validated()));
54: 
55:         return CouponResource::make($coupon);
56:     }
57: 
58:     public function destroy(Coupon $coupon): JsonResponse
59:     {
60:         // سجل الاستخدام تاريخ مالي: كوبون مُستخدَم لا يُحذف، يُعطَّل (M9)
61:         if ($coupon->usages()->exists()) {
62:             throw new BusinessException('لا يمكن حذف كوبون له استخدامات مسجلة؛ عطّله بدلًا من حذفه.');
63:         }
64:         // فكّ ارتباط السلال المعلقة حتى لا يتعطل إتمام شرائها (M9)
65:         Cart::query()->where('coupon_id', $coupon->id)->update(['coupon_id' => null]);
66:         $coupon->delete();
67: 
68:         return response()->json(['message' => 'تم حذف الكوبون']);
69:     }
70: 
71:     /**
72:      * ‏null صريح لحقول NOT NULL يُحذف من الحمولة بدل ما يكسر الحفظ بـ 500 (M8).
73:      *
74:      * @param  array<string, mixed>  $data
75:      * @return array<string, mixed>
76:      */
77:     private function withoutNulls(array $data): array
78:     {
79:         foreach (['value', 'usage_limit_per_customer', 'is_active'] as $key) {
80:             if (array_key_exists($key, $data) && $data[$key] === null) {
81:                 unset($data[$key]);
82:             }
83:         }
84: 
85:         return $data;
86:     }
87: } 1: <?php
