 5: namespace App\Http\Controllers\Api\V1\Webhook;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Services\PaymentWebhookService;
 9: use Illuminate\Http\JsonResponse;
10: use Illuminate\Http\Request;
11: 
12: /**
13:  * ويب هوك بوابات الدفع — بلا مصادقة Sanctum؛ الحماية بنمط توقيع
14:  * كل بوابة (driver) وبالتسجيل في webhook_logs (Idempotency).
15:  */
16: class PaymentWebhookController extends Controller
17: {
18:     public function __construct(private readonly PaymentWebhookService $webhooks) {}
19: 
20:     public function handle(Request $request, string $gateway): JsonResponse
21:     {
22:         $payload = json_decode($request->getContent(), true);
23:         // الهيدرات بمفاتيح صغيرة + الـ query: أنماط Paymob (hmac في query)
24:         // وStripe (هيدر موقّع) تحتاج أكثر من هيدر واحد (F-06)
25:         $headers = collect($request->headers->all())
26:             ->map(fn (array $values): ?string => $values[0] ?? null)
27:             ->all();
28:         $result = $this->webhooks->handle(
29:             $gateway,
30:             is_array($payload) ? $payload : [],
31:             $request->getContent(),
32:             $headers,
33:             $request->query(),
34:             $request->ip(),
35:         );
36: 
37:         return response()->json($result['body'], $result['http']);
38:     }
39: } 1: <?php
