 5: namespace App\Http\Requests\Admin\Promotion;
 6: 
 7: use Illuminate\Foundation\Http\FormRequest;
 8: use Illuminate\Validation\Rule;
 9: 
10: class CouponRequest extends FormRequest
11: {
12:     public function authorize(): bool
13:     {
14:         return true;
15:     }
16: 
17:     /** @return array<string, mixed> */
18:     public function rules(): array
19:     {
20:         $coupon = $this->route('coupon');
21: 
22:         return [
23:             'code' => ['required', 'string', 'max:50', Rule::unique('coupons', 'code')->ignore($coupon)],
24:             'type' => ['required', Rule::in(['percentage', 'fixed', 'free_shipping'])],
25:             // كوبون نسبي فوق 100% يعني خصمًا كاملًا وأكثر — ممنوع (M18)
26:             'value' => ['nullable', 'numeric', 'min:0', Rule::when($this->input('type') === 'percentage', ['max:100'])],
27:             'max_discount_amount' => ['nullable', 'numeric', 'min:0'],
28:             'min_order_amount' => ['nullable', 'numeric', 'min:0'],
29:             'usage_limit' => ['nullable', 'integer', 'min:1'],
30:             'usage_limit_per_customer' => ['nullable', 'integer', 'min:0'],
31:             'starts_at' => ['nullable', 'date'],
32:             'ends_at' => ['nullable', 'date', 'after_or_equal:starts_at'],
33:             'is_active' => ['nullable', 'boolean'],
