  5: namespace App\Services;
  6: 
  7: /**
  8:  * التحقق من توقيعات الويب هوك بأنماط البوابات الحقيقية (F-06):
  9:  * - hmac (الافتراضي): HMAC-SHA256 للنص الخام في هيدر واحد.
 10:  * - stripe: هيدر Stripe-Signature بصيغة t=…,v1=… والتوقيع على "{t}.{body}"
 11:  *   مع فحص حداثة الطابع الزمني (≤ 300 ثانية) ضد إعادة الإرسال.
 12:  * - paymob: معامل hmac في الـ query — HMAC-SHA512 لحقول المعاملة
 13:  *   بترتيب Paymob الرسمي المنشور.
 14:  * - moyasar: secret_token داخل جسم الطلب يطابق السر المضبوط.
 15:  * كل المقارنات hash_equals. لا مكتبات خارجية.
 16:  */
 17: class WebhookSignatureVerifier
 18: {
 19:     public function verify(?string $secret, string $rawBody, ?string $signature): bool
 20:     {
 21:         if ($secret === null || $secret === '' || $signature === null || $signature === '') {
 22:             return false;
 23:         }
 24: 
 25:         if (str_starts_with($signature, 'sha256=')) {
 26:             $signature = substr($signature, 7);
 27:         }
 28: 
 29:         $expected = hash_hmac('sha256', $rawBody, $secret);
 30: 
 31:         return hash_equals($expected, strtolower(trim($signature)));
 32:     }
 33: 
 34:     /**
 35:      * @param  array<string, string|null>  $headers  مفاتيح بحروف صغيرة
 36:      * @param  array<string, mixed>  $query
 37:      * @param  array<string, mixed>  $payload
 38:      */
 39:     public function verifyGateway(string $driver, ?string $secret, string $rawBody, array $headers, array $query, array $payload, ?string $signatureHeader = null): bool
 40:     {
 41:         return match ($driver) {
 42:             'stripe' => $this->verifyStripe($secret, $rawBody, $headers),
 43:             'paymob' => $this->verifyPaymob($secret, $query, $payload),
 44:             'moyasar' => $this->verifyMoyasar($secret, $payload),
 45:             default => $this->verify(
 46:                 $secret,
 47:                 $rawBody,
 48:                 $headers[strtolower($signatureHeader ?? 'X-Webhook-Signature')] ?? null,
 49:             ),
 50:         };
 51:     }
 52: 
 53:     /** @param array<string, string|null> $headers */
 54:     private function verifyStripe(?string $secret, string $rawBody, array $headers): bool
 55:     {
 56:         $header = $headers['stripe-signature'] ?? null;
 57:         if ($secret === null || $secret === '' || $header === null || $header === '') {
 58:             return false;
 59:         }
 60: 
 61:         $timestamp = null;
 62:         $signatures = [];
 63:         foreach (explode(',', $header) as $part) {
 64:             $pair = explode('=', trim($part), 2);
 65:             if (count($pair) !== 2) {
 66:                 continue;
 67:             }
 68:             if ($pair[0] === 't') {
 69:                 $timestamp = $pair[1];
 70:             } elseif ($pair[0] === 'v1') {
 71:                 $signatures[] = $pair[1];
 72:             }
 73:         }
 74:         if ($timestamp === null || $signatures === [] || ! ctype_digit($timestamp)) {
 75:             return false;
 76:         }
 77:         // حماية من إعادة الإرسال: طابع أقدم من 5 دقائق يُرفض
 78:         if (abs(time() - (int) $timestamp) > 300) {
 79:             return false;
 80:         }
 81: 
 82:         $expected = hash_hmac('sha256', $timestamp.'.'.$rawBody, $secret);
 83:         foreach ($signatures as $signature) {
 84:             if (hash_equals($expected, strtolower(trim($signature)))) {
 85:                 return true;
 86:             }
 87:         }
 88: 
 89:         return false;
 90:     }
 91: 
 92:     /**
 93:      * @param  array<string, mixed>  $query
 94:      * @param  array<string, mixed>  $payload
 95:      */
 96:     private function verifyPaymob(?string $secret, array $query, array $payload): bool
 97:     {
 98:         $hmac = $query['hmac'] ?? null;
 99:         if ($secret === null || $secret === '' || ! is_string($hmac) || $hmac === '') {
100:             return false;
101:         }
102: 
103:         $tx = isset($payload['obj']) && is_array($payload['obj']) ? $payload['obj'] : $payload;
104:         // ترتيب حقول Paymob الرسمي لرسالة الـ callback
105:         $fields = [
106:             'amount_cents', 'created_at', 'currency', 'error_occured',
107:             'has_parent_transaction', 'id', 'integration_id', 'is_3d_secure',
108:             'is_auth', 'is_capture', 'is_refunded', 'is_standalone_payment',
109:             'is_voided', 'order.id', 'owner', 'pending',
110:             'source_data.pan', 'source_data.sub_type', 'source_data.type', 'success',
111:         ];
112:         $concatenated = '';
113:         foreach ($fields as $field) {
114:             $value = data_get($tx, $field);
115:             if (is_bool($value)) {
116:                 $concatenated .= $value ? 'true' : 'false';
117:             } elseif (is_scalar($value)) {
118:                 $concatenated .= (string) $value;
119:             }
120:         }
121: 
122:         $expected = hash_hmac('sha512', $concatenated, $secret);
123: 
124:         return hash_equals($expected, strtolower(trim($hmac)));
125:     }
126: 
127:     /** @param array<string, mixed> $payload */
128:     private function verifyMoyasar(?string $secret, array $payload): bool
129:     {
130:         $token = $payload['secret_token'] ?? null;
131:         if ($secret === null || $secret === '' || ! is_string($token) || $token === '') {
132:             return false;
133:         }
134: 
135:         return hash_equals($secret, $token);
136:     }
137: } 1: <?php
