154:     // ---------- helpers ----------
155: 
156:     private function orderFromCart(ProductVariant $variant, float|int $qty): Order
157:     {
158:         $cart = Cart::create([]);
159:         $cart->items()->create(['product_variant_id' => $variant->id, 'qty' => $qty]);
160: 
161:         return app(OrderService::class)->createFromCart($cart, [
162:             'recipient_name' => 'عميل', 'recipient_phone' => '01012345678',
163:             'payment_method' => 'cod',
164:         ]);
165:     }
166: 
167:     private function purchasableVariant(float $price): ProductVariant
168:     {
169:         $product = Product::factory()->create(['status' => 'published']);
170: 
171:         return ProductVariant::factory()->create([
172:             'product_id' => $product->id,
173:             'retail_price' => $price,
174:         ]);
175:     }
176: 
177:     private function giveStock(ProductVariant $variant, float|int $qty, ?Branch $branch = null): void
178:     {
179:         app(InventoryService::class)->recordMovement([
180:             'product_variant_id' => $variant->id,
181:             'branch_id' => ($branch ?? $this->branch)->id,
182:             'type' => StockMovementType::AdjustmentIn,
183:             'affected_bucket' => StockBucket::OnHand,
184:             'quantity' => $qty,
185:             'created_by' => $this->admin->id,
186:         ]);
187:     }
188: 
189:     private function level(int $variantId, ?Branch $branch = null): StockLevel
190:     {
191:         return StockLevel::query()
192:             ->where('product_variant_id', $variantId)
193:             ->where('branch_id', ($branch ?? $this->branch)->id)
194:             ->whereNull('location_id')
195:             ->firstOrFail();
196:     }
197: 
198:     private function staffWithPermissions(array $permissions): User
199:     {
200:         foreach ($permissions as $permission) {
201:             Permission::findOrCreate($permission, 'staff');
202:         }
203:         $staff = User::factory()->create();
204:         $staff->givePermissionTo($permissions);
205: 
206:         return $staff;
207:     }
208: 
209:     private function api(string $method, string $uri, array $payload = []): TestResponse
210:     {
211:         Auth::forgetGuards();
212: 
213:         return $this->withToken($this->admin->createToken('t')->plainTextToken)
214:             ->json($method, $uri, $payload);
215:     }
