232:         $order->update(['status' => OrderStatus::Confirmed]);
233: 
234:         $result = app(OrderService::class)->changeStatus($order, OrderStatus::Processing, $customer);
235: 
236:         $history = $result->statusHistories->first();
237:         $this->assertSame(Customer::class, $history->changed_by_type);
238:         $this->assertSame($customer->id, $history->changed_by_id);
239:     }
