243:     private function giveStock(ProductVariant $variant, Branch $branch, float|int $qty): void
244:     {
245:         app(InventoryService::class)->recordMovement([
246:             'product_variant_id' => $variant->id,
247:             'branch_id' => $branch->id,
248:             'type' => StockMovementType::AdjustmentIn,
249:             'affected_bucket' => StockBucket::OnHand,
250:             'quantity' => $qty,
251:             'created_by' => $this->staff->id,
252:         ]);
253:     }
254: 
255:     /** @param array<int, array{0: ProductVariant, 1: float|int}> $lines */
256:     private function makeOrder(array $lines, ?int $cityId = null, ?int $customerId = null): Order
257:     {
258:         $order = Order::factory()->create([
259:             'city_id' => $cityId,
260:             'customer_id' => $customerId,
261:         ]);
262:         foreach ($lines as [$variant, $qty]) {
263:             OrderItem::factory()->forVariant($variant)->create([
264:                 'order_id' => $order->id,
265:                 'qty' => $qty,
266:                 'unit_price' => 100,
267:                 'line_total' => 100 * $qty,
268:             ]);
269:         }
270: 
271:         return $order->fresh(['items']);
272:     }
273: 
274:     private function level(int $variantId, int $branchId): StockLevel
275:     {
276:         return StockLevel::query()
277:             ->where('product_variant_id', $variantId)
278:             ->where('branch_id', $branchId)
279:             ->whereNull('location_id')
280:             ->firstOrFail();
281:     }
