 82:         $token = $this->postJson('/api/v1/store/cart/items', [
 83:             'product_variant_id' => $variant->id, 'qty' => $qty,
 84:         ])->assertOk()->json('data.cart_token');
 85:         $id = $this->withHeaders(['X-Cart-Session' => $token])->postJson('/api/v1/store/checkout', [
 86:             'recipient_name' => 'ضيف', 'recipient_phone' => '01012345678',
 87:             'city_id' => $city->id, 'shipping_address_line' => 'عنوان', 'payment_method' => $payment,
 88:         ])->assertCreated()->json('data.id');
