 84:         // من النسخة القديمة يبدو الانتقال Confirmed→Shipped قانونيًا، لكن الحالة
 85:         // الطازجة Cancelled فيجب أن يُرفض وألا يُفك الحجز مرة ثانية
 86:         try {
 87:             $service->changeStatus($staleCopy, OrderStatus::Shipped, $this->admin);
 88:             $this->fail('انتقال من حالة ملغاة كان يجب أن يُرفض');
 89:         } catch (BusinessException) {
 90:             $this->assertSame('0.0000', (string) $this->level($variant->id)->reserved);
 91:             $this->assertSame('10.0000', (string) $this->level($variant->id)->on_hand);
 92:         }
