309:     // ---------- helpers ----------
310: 
311:     private function shipOrder(Order $order, ShippingCompany $company, ?string $awb = null): Order
312:     {
313:         app(ShipmentService::class)->createForOrder($order, $company->id, $awb, $this->admin);
314: 
315:         return $order->fresh();
316:     }
317: 
318:     private function postWebhook(string $uri, array $payload, string $secret): TestResponse
319:     {
320:         $body = json_encode($payload);
321: 
322:         return $this->call('POST', $uri, [], [], [], [
323:             'HTTP_X-Webhook-Signature' => hash_hmac('sha256', $body, $secret),
324:             'CONTENT_TYPE' => 'application/json',
325:             'HTTP_ACCEPT' => 'application/json',
326:         ], $body);
327:     }
328: 
329:     private function makeOrder(ProductVariant $variant, float|int $qty, string $paymentMethod): Order
330:     {
331:         $cart = Cart::create([]);
332:         $cart->items()->create(['product_variant_id' => $variant->id, 'qty' => $qty]);
333: 
334:         return app(OrderService::class)->createFromCart($cart, [
335:             'recipient_name' => 'عميل', 'recipient_phone' => '01012345678',
336:             'payment_method' => $paymentMethod,
337:         ]);
338:     }
339: 
340:     private function purchasableVariant(float $price): ProductVariant
341:     {
342:         $product = Product::factory()->create(['status' => 'published']);
343: 
344:         return ProductVariant::factory()->create([
345:             'product_id' => $product->id,
346:             'retail_price' => $price,
347:         ]);
348:     }
349: 
350:     private function giveStock(ProductVariant $variant, float|int $qty): void
351:     {
352:         app(InventoryService::class)->recordMovement([
353:             'product_variant_id' => $variant->id,
354:             'branch_id' => $this->branch->id,
355:             'type' => StockMovementType::AdjustmentIn,
356:             'affected_bucket' => StockBucket::OnHand,
357:             'quantity' => $qty,
358:             'created_by' => $this->admin->id,
359:         ]);
360:     }
361: 
362:     private function level(int $variantId): StockLevel
363:     {
364:         return StockLevel::query()
365:             ->where('product_variant_id', $variantId)
366:             ->where('branch_id', $this->branch->id)
367:             ->whereNull('location_id')
368:             ->firstOrFail();
369:     }
