18: /**
19:  * طلبات المتجر: تتبع عام (برقم الطلب + هاتف الطلب)،
20:  * وطلبات حساب العميل المسجل وعرضها وإلغاؤها الذاتي.
21:  */
22: class OrderController extends Controller
23: {
24:     public function __construct(private readonly OrderService $orders) {}
25: 
26:     /** تتبع عام: رقم الطلب + رقم هاتف الطلب للتحقق. */
27:     public function track(Request $request, string $number): TrackOrderResource
28:     {
29:         $request->validate(['phone' => ['required', 'string', 'max:50']]);
30: 
31:         $order = Order::query()
32:             ->where('order_number', $number)
33:             ->with(['items', 'statusHistories'])
34:             ->first();
35: 
36:         // مقارنة بعد توحيد صيغة الهاتف على الجانبين (M5)
37:         $inputPhone = Customer::normalizePhone((string) $request->input('phone'));
38:         $phoneMatches = $order !== null
39:             && (($order->guest_phone !== null && Customer::normalizePhone($order->guest_phone) === $inputPhone)
40:                 || ($order->customer?->phone !== null && Customer::normalizePhone($order->customer->phone) === $inputPhone));
41: 
42:         if (! $phoneMatches) {
43:             abort(404);
44:         }
45: 
46:         return TrackOrderResource::make($order);
47:     }
48: 
49:     public function index(Request $request): AnonymousResourceCollection
50:     {
51:         /** @var Customer $customer */
52:         $customer = $request->user();
53: 
54:         $orders = Order::query()
55:             ->where('customer_id', $customer->id)
56:             ->with('items')
57:             ->latest('id')
58:             ->paginate(15);
59: 
60:         return OrderResource::collection($orders);
61:     }
62: 
63:     public function cancel(Request $request, int $order): OrderResource
64:     {
65:         /** @var Customer $customer */
66:         $customer = $request->user();
67: 
68:         $order = Order::query()->where('customer_id', $customer->id)->findOrFail($order);
69: 
70:         if (! in_array($order->status, [OrderStatus::Pending, OrderStatus::Confirmed], true)) {
71:             throw new BusinessException('لا يمكن إلغاء الطلب في حالته الحالية؛ الإلغاء متاح قبل بدء التجهيز والشحن فقط.');
72:         }
73: 
74:         // الفحص على النسخة المقفولة داخل changeStatus (F-11): الفحص أعلاه
75:         // على نسخة غير مقفولة لا يكفي ضد انتقال متزامن إلى Processing
76:         $order = $this->orders->changeStatus($order, OrderStatus::Cancelled, $customer, 'ألغاه العميل من حسابه',
77:             [OrderStatus::Pending, OrderStatus::Confirmed]);
78: 
79:         return OrderResource::make($order->load('items'));
80:     }
