  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Enums\OrderStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Http\Controllers\Controller;
 10: use App\Http\Requests\Admin\Order\AllocateOrderRequest;
 11: use App\Http\Requests\Admin\Order\CreateShipmentRequest;
 12: use App\Http\Requests\Admin\Order\UpdateOrderStatusRequest;
 13: use App\Http\Resources\Admin\AdminOrderResource;
 14: use App\Http\Resources\Admin\ShipmentResource;
 15: use App\Models\Order;
 16: use App\Services\OrderAllocationService;
 17: use App\Services\OrderService;
 18: use App\Services\ShipmentService;
 19: use Illuminate\Http\Request;
 20: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 21: use Illuminate\Routing\Controllers\HasMiddleware;
 22: use Illuminate\Routing\Controllers\Middleware;
 23: use Illuminate\Support\Carbon;
 24: use Illuminate\Validation\Rule;
 25: 
 26: /** إدارة الطلبات: عرض وفلترة، تغيير الحالة عبر OrderService، وتوزيع يدوي/مُجبر. */
 27: class OrderController extends Controller implements HasMiddleware
 28: {
 29:     public function __construct(
 30:         private readonly OrderService $orders,
 31:         private readonly OrderAllocationService $allocation,
 32:         private readonly ShipmentService $shipments,
 33:     ) {}
 34: 
 35:     public static function middleware(): array
 36:     {
 37:         return [
 38:             new Middleware('can:orders.view', only: ['index', 'show']),
 39:             new Middleware('can:orders.update', only: ['updateStatus', 'createShipment']),
 40:             new Middleware('can:orders.allocate', only: ['allocate']),
 41:         ];
 42:     }
 43: 
 44:     public function index(Request $request): AnonymousResourceCollection
 45:     {
 46:         $filters = $request->validate([
 47:             'status' => ['nullable', Rule::in(array_column(OrderStatus::cases(), 'value'))],
 48:             'allocated_branch_id' => ['nullable', 'integer', 'min:1'],
 49:             'payment_method' => ['nullable', Rule::in(['cod', 'card', 'wallet', 'bank_transfer', 'credit'])],
 50:             'date_from' => ['nullable', 'date'],
 51:             'date_to' => ['nullable', 'date'],
 52:             'search' => ['nullable', 'string', 'max:100'],
 53:             // تظهر العلامتان في المورد بلا شاشة تصفية (F-29): تُتاح الآن كفلتر
 54:             'needs_attention' => ['nullable', 'boolean'],
 55:             'requires_refund' => ['nullable', 'boolean'],
 56:         ]);
 57: 
 58:         $orders = Order::query()
 59:             ->with(['customer', 'allocatedBranch'])
 60:             ->withCount('items')
 61:             ->when($filters['status'] ?? null, fn ($q, $status) => $q->where('status', $status))
 62:             ->when($filters['allocated_branch_id'] ?? null, fn ($q, $branchId) => $q->where('allocated_branch_id', $branchId))
 63:             ->when($filters['payment_method'] ?? null, fn ($q, $method) => $q->where('payment_method', $method))
 64:             ->when(array_key_exists('needs_attention', $filters) && $filters['needs_attention'] !== null,
 65:                 fn ($q) => $q->where('needs_attention', (bool) $filters['needs_attention']))
 66:             ->when(array_key_exists('requires_refund', $filters) && $filters['requires_refund'] !== null,
 67:                 fn ($q) => $q->where('requires_refund', (bool) $filters['requires_refund']))
 68:             // نطاق زمني بدل whereDate حتى يعمل فهرس created_at (M16)،
 69:             // بمنطقة العمل ثم يُخزّن/يُقارن بـ UTC
 70:             ->when($filters['date_from'] ?? null, fn ($q, $date) => $q->where('created_at', '>=',
 71:                 Carbon::parse($date, (string) config('app.business_timezone'))->startOfDay()->utc()))
 72:             ->when($filters['date_to'] ?? null, fn ($q, $date) => $q->where('created_at', '<',
 73:                 Carbon::parse($date, (string) config('app.business_timezone'))->startOfDay()->addDay()->utc()))
 74:             // بحث: رقم الطلب والهاتف بالبادئة (يستخدم الفهارس)، والاسم
 75:             // بالاحتواء مع تهريب محارف LIKE من مدخل المستخدم (M16)
 76:             ->when($filters['search'] ?? null, fn ($q, $term) => $q->where(function ($inner) use ($term): void {
 77:                 $escaped = str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], (string) $term);
 78:                 $inner->where('order_number', 'like', $escaped.'%')
 79:                     ->orWhere('guest_phone', 'like', $escaped.'%')
 80:                     ->orWhere('guest_name', 'like', '%'.$escaped.'%');
 81:             }))
 82:             ->latest('id')
 83:             ->paginate(20);
 84: 
 85:         return AdminOrderResource::collection($orders);
 86:     }
 87: 
 88:     public function show(Order $order): AdminOrderResource
 89:     {
 90:         return AdminOrderResource::make(
 91:             $order->load(['items', 'statusHistories', 'customer', 'city', 'allocatedBranch'])
 92:         );
 93:     }
 94: 
 95:     public function updateStatus(UpdateOrderStatusRequest $request, Order $order): AdminOrderResource
 96:     {
 97:         // الشحن له بوليصة ومسار مخزون: من إنشاء البوليصة فقط (L3) —
 98:         // وضع Shipped يدويًا يترك الطلب بلا بوليصة فلا يصله ويب هوك تسليم
