  5: namespace App\Services;
  6: 
  7: use App\Enums\StockBucket;
  8: use App\Enums\StockMovementType;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\Branch;
 11: use App\Models\Order;
 12: use App\Models\OrderItem;
 13: use App\Models\StockLevel;
 14: use Illuminate\Database\Eloquent\Builder;
 15: use Illuminate\Support\Facades\DB;
 16: 
 17: /**
 18:  * توزيع الطلب على الفروع وحجز مخزونه (reserved) عبر InventoryService حصرًا.
 19:  *
 20:  * الخوارزمية:
 21:  * 1. فرع مُجبر من الأدمن: يُتحقق من تغطيته ويُحجز منه.
 22:  * 2. أول فرع نشط واحد يغطي الطلب كاملًا — أولوية لفرع نفس مدينة العميل.
 23:  * 3. وإلا: كل صنف من الفرع الأعلى رصيدًا متاحًا له (الصنف كاملًا من فرع واحد).
 24:  *
 25:  * داخل الفرع الواحد قد يتوزع الصنف على أكثر من موقع (الأعلى متاحًا أولًا).
 26:  * أي نقص في أي صنف يُلغي العملية كلها (transaction واحدة — لا حجز جزئي يتسرب).
 27:  */
 28: class OrderAllocationService
 29: {
 30:     public function __construct(protected InventoryService $inventoryService) {}
 31: 
 32:     public function allocate(Order $order, ?int $forcedBranchId = null, ?int $performedBy = null): Order
 33:     {
 34:         return DB::transaction(function () use ($order, $forcedBranchId, $performedBy): Order {
 35:             // إعادة قراءة الطلب بقفل صف قبل فحص التوزيع السابق (C1)
 36:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
 37:             $order->load('items');
 38:             // ترتيب قفل عام ثابت (F-02): البنود بترتيب product_variant_id
 39:             // في كل المسارات حتى لا ينتظر طلبان بعضهما دائريًا (40P01)
 40:             $order->setRelation('items', $order->items
 41:                 ->sortBy(fn (OrderItem $item): int => (int) $item->product_variant_id)
 42:                 ->values());
 43:             $performedBy ??= auth()->id();
 44: 
 45:             if ($order->allocated_branch_id !== null
 46:                 || $order->items->contains(fn (OrderItem $item): bool => $item->allocated_branch_id !== null)) {
 47:                 throw new BusinessException('الطلب مُوزّع على الفروع من قبل؛ ألغِ التوزيع الحالي أولًا قبل إعادة التوزيع.');
 48:             }
 49: 
 50:             // 1. فرع مُجبر يدويًا
 51:             if ($forcedBranchId !== null) {
 52:                 $branch = Branch::query()->where('is_active', true)->find($forcedBranchId);
 53:                 if ($branch === null) {
 54:                     throw new BusinessException('الفرع المحدد غير موجود أو غير نشط.');
 55:                 }
 56:                 $this->reserveItemsFromBranch($order, $branch->id, $performedBy);
 57:                 $order->update(['allocated_branch_id' => $branch->id]);
 58: 
 59:                 return $order->fresh(['items']);
 60:             }
 61: 
 62:             // خريطة تغطية واحدة مجمّعة لكل الفروع والأصناف (M15) بدل
 63:             // استعلام لكل فرع × صنف — القرارات التالية كلها في الذاكرة
 64:             $coverage = $this->branchAvailabilityMap($order);
 65: 
 66:             // 2. فرع واحد يغطي الطلب كاملًا (أولوية لنفس مدينة العميل:
 67:             // بالمعرّف أولًا ثم بمطابقة الاسم كرجوع — L5)
 68:             $cityName = $order->city?->name_ar;
 69:             $branches = Branch::query()
 70:                 ->where('is_active', true)
 71:                 ->when($order->city_id !== null, fn (Builder $q): Builder => $q->orderByRaw('CASE WHEN city_id = ? THEN 0 ELSE 1 END', [$order->city_id]))
 72:                 ->when($cityName !== null, fn (Builder $q): Builder => $q->orderByRaw('city = ? DESC', [$cityName]))
 73:                 ->orderBy('id')
 74:                 ->get();
 75: 
 76:             foreach ($branches as $branch) {
 77:                 if ($this->canBranchFulfillFullOrder($order, $branch->id, $coverage)) {
 78:                     $this->reserveItemsFromBranch($order, $branch->id, $performedBy);
 79:                     $order->update(['allocated_branch_id' => $branch->id]);
 80: 
 81:                     return $order->fresh(['items']);
 82:                 }
 83:             }
 84: 
 85:             // 3. كل صنف من الفرع الأعلى رصيدًا متاحًا له
 86:             foreach ($order->items as $item) {
 87:                 $branchId = $this->bestBranchForItem($item, $coverage);
 88:                 if ($branchId === null) {
 89:                     throw new BusinessException("الرصيد المتاح غير كافٍ للصنف ({$item->sku_snapshot}) في أي فرع.");
 90:                 }
 91:                 $this->reserveItemFromBranch($order, $item, $branchId, $performedBy);
 92:                 $item->update(['allocated_branch_id' => $branchId]);
 93:             }
 94: 
 95:             return $order->fresh(['items']);
 96:         });
 97:     }
 98: 
 99:     /**
100:      * تغطية الفروع لأصناف الطلب باستعلام واحد مجمّع (M15):
101:      * ‏[branch_id][variant_id] => مجموع المتاح في المواقع النشطة.
102:      *
103:      * @return array<int, array<int, float>>
104:      */
105:     private function branchAvailabilityMap(Order $order): array
106:     {
107:         $variantIds = $order->items
108:             ->map(fn (OrderItem $item): int => (int) $item->product_variant_id)
109:             ->unique()->values()->all();
110: 
111:         $rows = StockLevel::query()
112:             ->whereIn('product_variant_id', $variantIds)
113:             ->whereHas('branch', fn (Builder $q): Builder => $q->where('is_active', true))
114:             ->where(fn (Builder $q): Builder => $q
115:                 ->whereNull('location_id')
116:                 ->orWhereHas('location', fn (Builder $l): Builder => $l->where('is_active', true)))
117:             ->groupBy('branch_id', 'product_variant_id')
118:             ->selectRaw('branch_id, product_variant_id, SUM(available) as total_available')
119:             ->get();
120: 
121:         $map = [];
122:         foreach ($rows as $row) {
123:             $map[(int) $row->branch_id][(int) $row->product_variant_id] = (float) $row->total_available;
124:         }
125: 
126:         return $map;
127:     }
128: 
129:     /** @param array<int, array<int, float>> $coverage */
130:     private function canBranchFulfillFullOrder(Order $order, int $branchId, array $coverage): bool
131:     {
132:         foreach ($order->items as $item) {
133:             if (($coverage[$branchId][(int) $item->product_variant_id] ?? 0) < (float) $item->qty) {
134:                 return false;
135:             }
136:         }
137: 
138:         return true;
139:     }
140: 
141:     /** @param array<int, array<int, float>> $coverage */
142:     private function bestBranchForItem(OrderItem $item, array $coverage): ?int
143:     {
144:         $best = null;
145:         $bestAvailable = 0.0;
146:         foreach ($coverage as $branchId => $variants) {
147:             $available = $variants[(int) $item->product_variant_id] ?? 0;
148:             if ($available >= (float) $item->qty && $available > $bestAvailable) {
149:                 $best = $branchId;
150:                 $bestAvailable = $available;
151:             }
152:         }
153: 
154:         return $best;
155:     }
156: 
157:     private function reserveItemsFromBranch(Order $order, int $branchId, ?int $performedBy): void
158:     {
159:         foreach ($order->items as $item) {
160:             $this->reserveItemFromBranch($order, $item, $branchId, $performedBy);
161:             $item->update(['allocated_branch_id' => $branchId]);
162:         }
163:     }
164: 
165:     /**
166:      * حجز كمية الصنف من فرع واحد، موزعة على مواقعه الأعلى متاحًا عند الحاجة.
167:      */
168:     private function reserveItemFromBranch(Order $order, OrderItem $item, int $branchId, ?int $performedBy): void
169:     {
170:         $remaining = (float) $item->qty;
171:         // قفل صفوف الأرصدة بترتيب ثابت (id) حتى لا يُحجز نفس الرصيد مرتين (H10)
172:         $levels = $this->usableLevels((int) $item->product_variant_id, $branchId)
173:             ->where('available', '>', 0)
174:             ->orderBy('id')
175:             ->lockForUpdate()
176:             ->get();
177: 
178:         foreach ($levels as $level) {
179:             if ($remaining <= 0) {
180:                 break;
181:             }
182:             $take = min((float) $level->available, $remaining);
183:             $this->inventoryService->recordMovement([
184:                 'product_variant_id' => (int) $item->product_variant_id,
185:                 'branch_id' => $branchId,
186:                 'location_id' => $level->location_id,
187:                 'type' => StockMovementType::Reserve,
188:                 'affected_bucket' => StockBucket::Reserved,
189:                 'quantity' => $take,
190:                 'reference_type' => Order::class,
191:                 'reference_id' => $order->id,
192:                 'created_by' => $performedBy,
193:                 'notes' => "حجز للطلب رقم {$order->order_number}",
194:             ]);
195:             $remaining -= $take;
196:         }
197: 
198:         if ($remaining > 0) {
199:             throw new BusinessException("الفرع المحدد لا يمتلك كمية كافية من الصنف ({$item->sku_snapshot}).");
200:         }
201:     }
202: 
203:     /**
204:      * صفوف رصيد قابلة للاستخدام: رصيد الفرع/المتغير في مواقع نشطة
205:      * (أو بلا موقع) — الحجز لا يخرج من موقع معطّل.
206:      *
207:      * @return Builder<StockLevel>
208:      */
209:     private function usableLevels(int $variantId, ?int $branchId = null): Builder
210:     {
211:         return StockLevel::query()
212:             ->where('product_variant_id', $variantId)
213:             ->when($branchId !== null, fn (Builder $q): Builder => $q->where('branch_id', $branchId))
214:             ->where(fn (Builder $q): Builder => $q
215:                 ->whereNull('location_id')
216:                 ->orWhereHas('location', fn (Builder $l): Builder => $l->where('is_active', true)));
217:     }
