  5: namespace App\Services;
  6: 
  7: use App\Enums\OrderStatus;
  8: use App\Enums\ShipmentStatus;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\Order;
 11: use App\Models\Shipment;
 12: use App\Models\ShippingCompany;
 13: use App\Models\ShippingRate;
 14: use App\Models\User;
 15: use Illuminate\Support\Facades\DB;
 16: use Illuminate\Support\Str;
 17: 
 18: /**
 19:  * إنشاء بوالص الشحن للطلبات.
 20:  * لا توجد بوابة شركة شحن مربوطة بعد: رقم البوليصة يُولّد داخليًا
 21:  * (أو يُمرّر جاهزًا من الأدمن)، وتكلفة البوليصة من جدول أسعار الشحن
 22:  * (شركة × منطقة مدينة الطلب) مع احترام حد الشحن المجاني.
 23:  */
 24: class ShipmentService
 25: {
 26:     public function __construct(protected OrderService $orders) {}
 27: 
 28:     public function createForOrder(Order $order, int $companyId, ?string $awbNumber, User $actor): Shipment
 29:     {
 30:         return DB::transaction(function () use ($order, $companyId, $awbNumber, $actor): Shipment {
 31:             // قفل الطلب والتحقق من حالته ومن عدم وجود بوليصة نشطة —
 32:             // نقرة مزدوجة لا تنتج بوليصتين ولا بيعًا مكررًا (H1)
 33:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
 34:             $hasActiveShipmentEarly = $order->shipments()
 35:                 ->whereNotIn('status', [ShipmentStatus::Failed->value, ShipmentStatus::Returned->value])
 36:                 ->exists();
 37:             // بوليصة بديلة (F-16): طلب مشحون كل بوالصه فاشلة/مرتجعة يمكن
 38:             // إعادة إصدار بوليصة له — بلا changeStatus (حالته Shipped أصلًا
 39:             // ومخزونه خرج مع الشحنة الأولى)
 40:             $isReplacement = $order->status === OrderStatus::Shipped
 41:                 && ! $hasActiveShipmentEarly
 42:                 && $order->shipments()->exists();
 43:             if (! in_array($order->status, [OrderStatus::Confirmed, OrderStatus::Processing], true) && ! $isReplacement) {
 44:                 throw new BusinessException('لا يمكن إنشاء بوليصة إلا لطلب مؤكد أو قيد التجهيز.');
 45:             }
 46:             // الدفع المسبق (غير COD) لا يُشحن إلا وحالته paid (F-05): طلب
 47:             // مسترد أو غير مدفوع لا يخرج من المستودع فيُشحن مجانًا. ضبط
 48:             // paid يدويًا (تحويل بنكي) قبل الشحن مقصود هنا
 49:             if ($order->payment_method !== 'cod' && $order->payment_status !== 'paid') {
 50:                 throw new BusinessException('لا يمكن شحن طلب دفع مسبق لم يُدفع بعد (الحالة الحالية: '.$order->payment_status.').');
 51:             }
 52:             if ($hasActiveShipmentEarly) {
 53:                 throw new BusinessException('توجد بوليصة نشطة لهذا الطلب بالفعل.');
 54:             }
 55: 
 56:             $company = ShippingCompany::query()->where('is_active', true)->find($companyId);
 57:             if ($company === null) {
 58:                 throw new BusinessException('شركة الشحن غير موجودة أو غير نشطة.');
 59:             }
 60: 
 61:             $rate = $this->rateFor($order, $company->id);
 62:             $shippingCost = $rate !== null ? (float) $rate->base_cost : (float) $order->shipping_cost;
 63:             if ($rate !== null && $rate->free_shipping_threshold !== null
 64:                 && ((float) $order->subtotal - (float) $order->discount_amount) >= (float) $rate->free_shipping_threshold) {
 65:                 $shippingCost = 0.0;
 66:             }
 67: 
 68:             $shipment = Shipment::create([
 69:                 'order_id' => $order->id,
 70:                 'shipping_company_id' => $company->id,
 71:                 'awb_number' => $awbNumber ?? $this->generateAwb($company),
 72:                 'status' => ShipmentStatus::Created,
 73:                 'label_url' => null,
 74:                 'shipping_cost' => $shippingCost,
 75:                 'cod_amount' => $order->payment_method === 'cod' ? (float) $order->grand_total : 0,
 76:                 'raw_response' => ['source' => 'internal'],
 77:             ]);
 78: 
 79:             // الشحن الفعلي للطلب (يفك الحجز ويخصم البيع) عبر بوابة الحالة —
 80:             // البديلة لا تستدعيه: الطلب مشحون ومخزونه خرج من الشحنة الأولى
 81:             if (! $isReplacement) {
 82:                 $this->orders->changeStatus($order, OrderStatus::Shipped, $actor, "تم إنشاء بوليصة الشحن {$shipment->awb_number}");
 83:             }
 84: 
 85:             return $shipment->fresh(['company', 'order']);
 86:         });
 87:     }
 88: 
 89:     /** سعر الشركة لمنطقة مدينة الطلب إن وُجد. */
 90:     /**
 91:      * سعر الشركة لمدينة الطلب: join مباشر rates × zone_cities مفلتر بالشركة
 92:      * والمدينة معًا — مدينة في أكثر من منطقة لا تختار منطقة بلا سعر (M12).
 93:      */
 94:     private function rateFor(Order $order, int $companyId): ?ShippingRate
 95:     {
 96:         if ($order->city_id === null) {
 97:             return null;
 98:         }
 99: 
100:         return ShippingRate::query()
101:             ->join('shipping_zones', 'shipping_zones.id', '=', 'shipping_rates.shipping_zone_id')
102:             ->join('shipping_zone_cities', 'shipping_zone_cities.shipping_zone_id', '=', 'shipping_zones.id')
103:             ->where('shipping_rates.shipping_company_id', $companyId)
104:             ->where('shipping_zone_cities.city_id', $order->city_id)
105:             ->where('shipping_zones.is_active', true)
106:             ->orderBy('shipping_rates.id')
107:             ->select('shipping_rates.*')
108:             ->first();
109:     }
110: 
111:     // تسعيرة العميل الموحدة في ShippingQuoteService (بلا تبعية دائرية)
112: 
113:     private function generateAwb(ShippingCompany $company): string
114:     {
115:         do {
116:             $awb = Str::upper($company->code).'-'.Str::upper(Str::random(10));
117:         } while (Shipment::query()->where('awb_number', $awb)->exists());
118: 
119:         return $awb;
120:     }
121: }  1: <?php
