  7: use App\Enums\CustomerStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Http\Controllers\Controller;
 10: use App\Http\Requests\Store\Checkout\CheckoutRequest;
 11: use App\Http\Requests\Store\Checkout\ShippingOptionsRequest;
 12: use App\Http\Resources\Store\OrderResource;
 13: use App\Models\Cart;
 14: use App\Models\City;
 15: use App\Models\Coupon;
 16: use App\Models\Customer;
 17: use App\Services\CartService;
 18: use App\Services\OrderService;
 19: use App\Services\ShippingQuoteService;
 20: use Illuminate\Http\JsonResponse;
 21: use Illuminate\Http\Request;
 22: 
 23: /** إتمام الشراء (زائر/مسجل) وخيارات الشحن. */
 24: class CheckoutController extends Controller
 25: {
 26:     public function __construct(
 27:         private readonly CartService $carts,
 28:         private readonly OrderService $orders,
 29:         private readonly ShippingQuoteService $shippingQuote,
 30:     ) {}
 31: 
 32:     public function shippingOptions(ShippingOptionsRequest $request): JsonResponse
 33:     {
 34:         $validated = $request->validated();
 35:         $city = City::query()->where('is_active', true)->findOrFail((int) $validated['city_id']);
 36:         [$customer, $cart] = $this->currentCart($request, create: false);
 37:         $totals = $this->carts->totals($cart, $customer);
 38: 
 39:         // نفس المدخلات التي سيحاسب عليها إتمام الشراء (M12 + F-29): البضاعة
 40:         // بعد خصم الكوبون، ورسوم COD حسب طريقة الدفع الفعلية لا cod دائمًا
 41:         $merchandise = max($totals['items_total'] - $totals['coupon_discount'], 0.0);
 42:         $cod = ($validated['payment_method'] ?? 'cod') === 'cod';
 43:         $quote = $this->shippingQuote->quoteForCity($city->id, $merchandise, $cod);
 44:         $rate = $quote['rate'];
 45: 
 46:         // كوبون الشحن المجاني يعفي تكلفة الشحن (لا رسوم COD) كما عند الشراء
 47:         $cost = $quote['cost'];
 48:         if ($totals['coupon_code'] !== null && $cart->coupon_id !== null
 49:             && Coupon::query()->whereKey($cart->coupon_id)->value('type') === 'free_shipping') {
 50:             $cost = 0.0;
 51:         }
 52: 
 53:         $days = $rate !== null ? "من {$rate->estimated_days_min} إلى {$rate->estimated_days_max} أيام عمل" : null;
 54: 
 55:         return response()->json(['data' => [
 56:             'city' => ['id' => $city->id, 'name_ar' => $city->name_ar, 'name_en' => $city->name_en],
 57:             'cart_total' => $totals['total'],
 58:             'options' => [[
 59:                 'key' => 'standard',
 60:                 'label' => 'شحن قياسي',
 61:                 'cost' => $cost,
 62:                 'cod_fee' => $quote['cod_fee'],
 63:                 'currency' => 'EGP',
 64:                 'estimated_days' => $days ?? 'من 2 إلى 4 أيام عمل',
 65:             ]],
 66:         ]]);
 67:     }
 68: 
 69:     public function store(CheckoutRequest $request): JsonResponse
 70:     {
 71:         [$customer, $cart] = $this->currentCart($request);
 72:         $data = $request->validated();
 73:         // هيدر اختياري: إعادة الإرسال بنفس المفتاح ترجع الطلب نفسه (F-13)
 74:         $idempotencyKey = $request->header('Idempotency-Key');
 75:         if (is_string($idempotencyKey) && $idempotencyKey !== '') {
 76:             $data['idempotency_key'] = $idempotencyKey;
 77:         }
 78: 
 79:         if ($customer === null && (empty($data['recipient_name']) || empty($data['recipient_phone']))) {
 80:             throw new BusinessException('بيانات المستلم (الاسم ورقم الهاتف) مطلوبة لإتمام الشراء كزائر.');
 81:         }
 82: 
 83:         $order = $this->orders->createFromCart($cart, $data, $customer);
 84: 
 85:         return response()->json([
 86:             'data' => OrderResource::make($order)->resolve($request),
