 16: /**
 17:  * سلة التسوق للزائر والعميل المسجل.
 18:  * - الزائر: سلة مربوطة بـ cart_token (يُرسل في هيدر X-Cart-Session).
 19:  * - العميل: سلة مربوطة بحسابه؛ وعند تسجيل الدخول تُدمج سلة الزائر فيها.
 20:  * الأسعار دائمًا لحظية من PricingService (لا تُخزّن في السلة أبدًا).
 21:  */
 22: class CartService
 23: {
 24:     public function __construct(
 25:         protected PricingService $pricing,
 26:         protected StoreCatalogService $catalog,
 27:         protected CouponService $coupons,
 28:     ) {}
 29: 
 30:     /**
 31:      * سلة الزائر/العميل الحالية.
 32:      * - التوكن غير الـ UUID يُتجاهل تمامًا (M2)؛ وتوكن أي سلة جديدة
 33:      *   يُولّد على الخادم دائمًا (Cart::booted) ولا يُقبل مقترح العميل.
 34:      * - بوضع القراءة ($create=false) لا يُحفظ أي صف: تُرجع سلة فارغة
 35:      *   افتراضية حتى لا تملأ الزواحف جدول carts (M3).
 36:      * لو وُجدت سلة زائر بالتوكن وعميل مسجل، تُدمج فيها أولًا.
 37:      */
 38:     public function resolveCart(?Customer $customer, ?string $guestToken, bool $create = true): Cart
 39:     {
 40:         $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
 41: 
 42:         if ($customer !== null) {
 43:             $cart = $create
 44:                 ? $this->accountCart($customer)
 45:                 : (Cart::query()->where('customer_id', $customer->id)->first() ?? new Cart(['customer_id' => $customer->id]));
 46:             if ($create && $guestToken !== null && $guestToken !== $cart->cart_token) {
 47:                 $this->mergeGuestCart($customer, $guestToken);
 48:                 $cart = $cart->fresh();
 49:             }
 50: 
 51:             return $cart->loadMissing('items');
 52:         }
 53: 
 54:         $cart = $guestToken !== null
 55:             ? Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')->first()
 56:             : null;
 57:         if ($cart !== null) {
 58:             return $cart->loadMissing('items');
 59:         }
 60: 
 61:         return ($create ? Cart::create([]) : new Cart)->loadMissing('items');
 62:     }
