 64:     /**
 65:      * سلة حساب العميل الوحيدة — القيد الفريد على customer_id يحسم السباق (M6).
 66:      * createOrFirst يغلّف الإدراج في savepoint داخل المعاملات (F-10):
 67:      * firstOrCreate العادي إذا فشل إدراجه هنا — والدمج كله داخل transaction
 68:      * خارجية — ترك المعاملة aborted (25P02) فخرج 500 رغم الـ catch.
 69:      */
 70:     private function accountCart(Customer $customer): Cart
 71:     {
 72:         return Cart::query()->where('customer_id', $customer->id)->first()
 73:             ?? Cart::query()->createOrFirst(['customer_id' => $customer->id]);
 74:     }
