 76:     /** دمج سلة زائر (بالتوكن) في سلة حساب العميل — تُستدعى عند تسجيل الدخول. */
 77:     public function mergeGuestCart(Customer $customer, ?string $guestToken): void
 78:     {
 79:         $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
 80:         if ($guestToken === null) {
 81:             return;
 82:         }
 83: 
 84:         // كل الدمج داخل transaction واحدة وسلة الزائر مقفولة: طلبات متوازية
 85:         // بعد تسجيل الدخول بنفس التوكن لا تضاعف الكميات (M6)
 86:         DB::transaction(function () use ($customer, $guestToken): void {
 87:             $guest = Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')
 88:                 ->lockForUpdate()->first();
 89:             if ($guest === null) {
 90:                 return;
 91:             }
 92:             if (! $guest->items()->exists()) {
 93:                 $guest->delete();
 94: 
 95:                 return;
 96:             }
 97: 
 98:             $account = $this->accountCart($customer);
 99:             foreach ($guest->items as $item) {
100:                 // UPSERT ذرّي: دمج متزامن لا يصطدم بقيد التفرد (F-09)
101:                 CartItem::query()->upsert(
102:                     [[
103:                         'cart_id' => $account->id,
104:                         'product_variant_id' => $item->product_variant_id,
105:                         'qty' => $item->qty,
106:                         'created_at' => now(),
107:                         'updated_at' => now(),
108:                     ]],
109:                     ['cart_id', 'product_variant_id'],
110:                     ['qty' => DB::raw('cart_items.qty + EXCLUDED.qty'), 'updated_at' => now()],
111:                 );
112:             }
113:             if ($account->coupon_id === null && $guest->coupon_id !== null) {
114:                 $account->update(['coupon_id' => $guest->coupon_id]);
115:             }
116:             $guest->items()->delete();
117:             $guest->delete();
118:         });
119:     }
