121:     public function addItem(Cart $cart, ?Customer $customer, int $variantId, float $qty): Cart
122:     {
123:         $variant = $this->purchasableVariant($variantId);
124:         $existing = $cart->items()->where('product_variant_id', $variantId)->first();
125:         $targetQty = ($existing !== null ? (float) $existing->qty : 0) + $qty;
126:         $this->assertAvailable($variantId, $targetQty);
127:         $this->assertPriced($variant, $customer, $targetQty);
128: 
129:         // كتابة ذرّية UPSERT (F-09): نقرتان متزامنتان على «أضف للسلة»
130:         // كانتا تصطدمان بقيد التفرد عند الإدراج الثاني فتخرج 500 —
131:         // ON CONFLICT تجمع الكمية على الصف نفسه. القراءة أعلاه تبقى
132:         // للتحقق من حد التوفر فقط
133:         CartItem::query()->upsert(
134:             [[
135:                 'cart_id' => $cart->id,
136:                 'product_variant_id' => $variantId,
137:                 'qty' => $qty,
138:                 'created_at' => now(),
139:                 'updated_at' => now(),
140:             ]],
141:             ['cart_id', 'product_variant_id'],
142:             ['qty' => DB::raw('cart_items.qty + EXCLUDED.qty'), 'updated_at' => now()],
143:         );
144: 
145:         return $cart->fresh('items');
146:     }
