148:     public function updateItemQty(Cart $cart, ?Customer $customer, int $variantId, float $qty): Cart
149:     {
150:         if ($qty <= 0) {
151:             return $this->removeItem($cart, $variantId);
152:         }
153:         $variant = $this->purchasableVariant($variantId);
154:         $this->assertAvailable($variantId, $qty);
155:         $this->assertPriced($variant, $customer, $qty);
156: 
157:         // UPSERT ذرّي بنفس منطق addItem — updateOrCreate كان يصطدم
158:         // بقيد التفرد تحت التزامن (F-09)، وهنا القيمة مطلقة لا تراكمية
159:         CartItem::query()->upsert(
160:             [[
161:                 'cart_id' => $cart->id,
162:                 'product_variant_id' => $variantId,
163:                 'qty' => $qty,
164:                 'created_at' => now(),
165:                 'updated_at' => now(),
166:             ]],
167:             ['cart_id', 'product_variant_id'],
168:             ['qty' => $qty, 'updated_at' => now()],
169:         );
170: 
171:         return $cart->fresh('items');
172:     }
