181:     /**
182:      * بنود السلة بأسعار لحظية من PricingService.
183:      * بند غير قابل للتسعير يرجع بـ unit_price = null (العرض يتجاوزه،
184:      * وإتمام الشراء يرفضه — يتحقق المستدعي).
185:      *
186:      * @return array<int, array{variant: ProductVariant, qty: float, unit_price: float|null, base_price: float|null, line_discount: float, line_total: float}>
187:      */
188:     public function pricedLines(Cart $cart, ?Customer $customer): array
189:     {
190:         $cart->loadMissing('items.variant.product');
191:         $lines = [];
192:         foreach ($cart->items as $item) {
193:             $variant = $item->variant;
194:             $qty = (float) $item->qty;
195:             try {
196:                 $resolved = $this->pricing->resolve($variant, $customer, $qty);
197:                 $unit = (float) $resolved['unit_price'];
198:                 $base = (float) $resolved['base_price'];
199:                 $lines[] = [
200:                     'item_id' => $item->id,
201:                     'variant' => $variant,
202:                     'qty' => $qty,
203:                     'unit_price' => $unit,
204:                     'base_price' => $base,
205:                     'line_discount' => round(($base - $unit) * $qty, 2),
206:                     'line_total' => round($unit * $qty, 2),
207:                 ];
208:             } catch (BusinessException) {
209:                 $lines[] = [
210:                     'item_id' => $item->id,
211:                     'variant' => $variant,
212:                     'qty' => $qty,
213:                     'unit_price' => null,
214:                     'base_price' => null,
215:                     'line_discount' => 0.0,
216:                     'line_total' => 0.0,
217:                 ];
218:             }
219:         }
220: 
221:         return $lines;
222:     }
223: 
224:     /**
225:      * ملخص السلة المالي بالأسعار اللحظية.
226:      *
227:      * @return array{subtotal: float, pricing_discount: float, items_total: float, coupon_discount: float, total: float, coupon_code: string|null}
228:      */
229:     /**
230:      * @param  array<int, array<string, mixed>>|null  $lines  بنود محسوبة مسبقًا
231:      *                                                        لتجنب إعادة التسعير (M15)
232:      */
233:     public function totals(Cart $cart, ?Customer $customer, ?array $lines = null): array
234:     {
235:         $lines ??= $this->pricedLines($cart, $customer);
236:         $subtotal = 0.0;
237:         $itemsTotal = 0.0;
238:         foreach ($lines as $line) {
239:             if ($line['unit_price'] === null) {
240:                 continue;
241:             }
242:             // كل سطر يُقرَّب أولًا ثم تُجمع القيم المقرّبة (M17)
243:             $subtotal += round((float) $line['base_price'] * $line['qty'], 2);
244:             $itemsTotal += $line['line_total'];
245:         }
246: 
247:         // الخصم السعري = الفرق بين الإجماليين المقرّبين، لا مجموع فروق
248:         // السطور المقرّبة (F-26) حتى لا يظهر فرق قرش بين العرض والمحصّل
249:         $pricingDiscount = round($subtotal - $itemsTotal, 2);
250: 
251:         $couponDiscount = 0.0;
252:         $couponCode = null;
253:         if ($cart->coupon_id !== null && $itemsTotal > 0) {
254:             try {
255:                 $coupon = $this->coupons->redeemableById((int) $cart->coupon_id, $itemsTotal, $customer);
256:                 $couponDiscount = $this->coupons->discountFor($coupon, $itemsTotal);
257:                 $couponCode = $coupon->code;
258:             } catch (BusinessException) {
259:                 // كوبون لم يعد صالحًا: يُعرض الملخص بدونه (إتمام الشراء سيعيد التحقق)
260:             }
261:         }
262: 
263:         return [
264:             'subtotal' => round($subtotal, 2),
265:             'pricing_discount' => round($pricingDiscount, 2),
266:             'items_total' => round($itemsTotal, 2),
267:             'coupon_discount' => $couponDiscount,
268:             'total' => round($itemsTotal - $couponDiscount, 2),
269:             'coupon_code' => $couponCode,
270:         ];
271:     }
