273:     /**
274:      * إعادة التحقق من قابلية البيع لكل بند لحظة الشراء بشكل مجمّع (M14):
275:      * متغير معطّل أو منتج غير منشور/محذوف ناعمًا بعد الإضافة يوقف الطلب.
276:      *
277:      * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
278:      */
279:     public function assertLinesPurchasable(array $lines): void
280:     {
281:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
282:         $variants = ProductVariant::query()->with('product')
283:             ->whereIn('id', $ids)->get()->keyBy('id');
284:         foreach ($lines as $line) {
285:             $variant = $variants->get($line['variant']->id) ?? $line['variant'];
286:             if (! $variant->is_active || $variant->product === null
287:                 || $variant->product->status !== ProductStatus::Published || $variant->product->trashed()) {
288:                 throw new BusinessException("الصنف ({$variant->sku}) لم يعد متاحًا للبيع؛ أزله من السلة وأعد المحاولة.");
289:             }
290:         }
291:     }
292: 
293:     /**
294:      * إعادة التحقق من توفر بنود مُسعّرة لحظة الشراء.
295:      *
296:      * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
297:      */
298:     public function assertLinesAvailable(array $lines): void
299:     {
300:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
301:         $map = $this->catalog->availabilityMap($ids);
302:         foreach ($lines as $line) {
303:             if (($map[$line['variant']->id] ?? 0) < $line['qty']) {
304:                 throw new BusinessException("الكمية المتاحة من الصنف ({$line['variant']->sku}) لم تعد كافية لإتمام الطلب.");
305:             }
306:         }
307:     }
308: 
309:     /**
310:      * تمثيل السلة للعرض: البنود بأسعار ومتاح لحظي + الملخص المالي.
311:      *
312:      * @return array<string, mixed>
313:      */
314:     public function present(Cart $cart, ?Customer $customer): array
315:     {
316:         $lines = $this->pricedLines($cart, $customer);
317:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
318:         $availability = $this->catalog->availabilityMap($ids);
319: 
320:         $items = [];
321:         foreach ($lines as $line) {
322:             $variant = $line['variant'];
323:             $items[] = [
324:                 'id' => $line['item_id'],
325:                 'product_variant_id' => $variant->id,
326:                 'product_id' => $variant->product_id,
327:                 'product_name' => $variant->product?->name_ar,
328:                 'sku' => $variant->sku,
329:                 'qty' => $line['qty'],
330:                 'unit_price' => $line['unit_price'],
331:                 'base_price' => $line['base_price'],
332:                 'line_discount' => $line['line_discount'],
333:                 'line_total' => $line['line_total'],
334:                 'available' => $availability[$variant->id] ?? 0,
335:                 'priced' => $line['unit_price'] !== null,
336:             ];
337:         }
338: 
339:         return [
340:             'id' => $cart->id,
341:             'cart_token' => $cart->cart_token,
342:             'customer_id' => $cart->customer_id,
343:             'items' => $items,
344:             'totals' => $this->totals($cart, $customer, $lines),
345:         ];
346:     }
