348:     private function purchasableVariant(int $variantId): ProductVariant
349:     {
350:         $variant = ProductVariant::query()->with('product')->find($variantId);
351:         if ($variant === null || ! $variant->is_active || $variant->product === null
352:             || $variant->product->status !== ProductStatus::Published || $variant->product->trashed()) {
353:             throw new BusinessException('الصنف غير متاح للشراء.');
354:         }
355: 
356:         return $variant;
357:     }
