359:     private function assertAvailable(int $variantId, float $qty): void
360:     {
361:         $available = $this->catalog->availabilityMap([$variantId])[$variantId] ?? 0;
362:         if ($available < $qty) {
363:             throw new BusinessException('الكمية المطلوبة غير متاحة حاليًا لهذا الصنف.');
364:         }
365:     }
