  5: namespace App\Services;
  6: 
  7: use App\Enums\OrderStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\Cart;
 10: use App\Models\Coupon;
 11: use App\Models\CouponUsage;
 12: use App\Models\Customer;
 13: use App\Models\Order;
 14: 
 15: /**
 16:  * التحقق من الكوبونات وربطها بالسلة وحساب خصمها وتسجيل استخدامها.
 17:  * الفحوص: التفعيل، النافذة الزمنية، الحد الكلي للاستخدام، حد العميل
 18:  * الواحد (usage_limit_per_customer — افتراضي 1)، والحد الأدنى للسلة.
 19:  * الخصم النسبي: min(subtotal × value/100, max_discount_amount).
 20:  * كوبون free_shipping خصمه المالي على البضاعة صفر — أثره إلغاء الشحن
 21:  * عند إتمام الشراء (يُسجل مبلغ الشحن المُعفى في سجل الاستخدام).
 22:  */
 23: class CouponService
 24: {
 25:     // رسالة موحّدة لعدم صلاحية الكود (F-24): «غير موجود» و«موجود لكن غير
 26:     // قابل للاستخدام» يجب ألا يتيحا تمييز وجود الكود بالتخمين
 27:     private const NOT_REDEEMABLE = 'كود الخصم غير صحيح أو غير متاح أو انتهت صلاحيته أو استُنفد حد استخدامه.';
 28: 
 29:     public function validateAndApply(Cart $cart, string $code, float $subtotal, ?Customer $customer = null): float
 30:     {
 31:         $coupon = $this->findRedeemable($code, $subtotal, $customer);
 32: 
 33:         $cart->update(['coupon_id' => $coupon->id]);
 34: 
 35:         return $this->discountFor($coupon, $subtotal);
 36:     }
 37: 
 38:     /** يتحقق من كوبون مرتبط بسلة (عند إتمام الشراء) ويرجعه أو يرمي استثناءً. */
 39:     public function redeemableById(int $couponId, float $subtotal, ?Customer $customer = null, ?string $guestPhone = null): Coupon
 40:     {
 41:         $coupon = Coupon::query()->find($couponId);
 42:         if ($coupon === null) {
 43:             throw new BusinessException('الكوبون المرتبط بالسلة لم يعد موجودًا.');
 44:         }
 45:         $this->assertRedeemable($coupon, $subtotal, $customer, $guestPhone);
 46: 
 47:         return $coupon;
 48:     }
 49: 
 50:     /** خصم البضاعة: النسبي بسقف، والثابت بحد الإجمالي، والشحن المجاني صفر هنا. */
 51:     public function discountFor(Coupon $coupon, float $subtotal): float
 52:     {
 53:         if ($subtotal <= 0 || $coupon->type === 'free_shipping') {
 54:             return 0.0;
 55:         }
 56: 
 57:         $discount = $coupon->type === 'percentage'
 58:             ? $subtotal * (float) $coupon->value / 100
 59:             : (float) $coupon->value;
 60: 
 61:         if ($coupon->max_discount_amount !== null) {
 62:             $discount = min($discount, (float) $coupon->max_discount_amount);
 63:         }
 64: 
 65:         return round(min($discount, $subtotal), 2);
 66:     }
 67: 
 68:     /** تسجيل استخدام فعلي عند إتمام الطلب + تحديث العداد الكلي. */
 69:     public function recordUsage(Coupon $coupon, Order $order, ?Customer $customer, float $discountAmount): CouponUsage
 70:     {
 71:         $usage = CouponUsage::create([
 72:             'coupon_id' => $coupon->id,
 73:             'customer_id' => $customer?->id,
 74:             'order_id' => $order->id,
 75:             'discount_amount' => $discountAmount,
 76:             // هاتف الزائر الموحد يُخزَّن مع الاستخدام لفحص الحد لاحقًا في SQL (F-04)
 77:             'guest_phone_normalized' => $customer === null && $order->guest_phone !== null
 78:                 ? Customer::normalizePhone($order->guest_phone)
 79:                 : null,
 80:         ]);
 81:         $coupon->increment('used_count');
 82: 
 83:         return $usage;
 84:     }
