 86:     private function findRedeemable(string $code, float $subtotal, ?Customer $customer): Coupon
 87:     {
 88:         $coupon = Coupon::query()->where('code', strtoupper(trim($code)))->first();
 89:         if ($coupon === null) {
 90:             throw new BusinessException(self::NOT_REDEEMABLE);
 91:         }
 92:         $this->assertRedeemable($coupon, $subtotal, $customer);
 93: 
 94:         return $coupon;
 95:     }
