 97:     private function assertRedeemable(Coupon $coupon, float $subtotal, ?Customer $customer, ?string $guestPhone = null): void
 98:     {
 99:         if (! $coupon->isRedeemableNow()) {
100:             throw new BusinessException(self::NOT_REDEEMABLE);
101:         }
102:         if ($coupon->min_order_amount !== null && $subtotal < (float) $coupon->min_order_amount) {
103:             throw new BusinessException('قيمة السلة أقل من الحد الأدنى لاستخدام هذا الكوبون.');
104:         }
105:         if ((int) $coupon->usage_limit_per_customer <= 0) {
106:             return;
107:         }
108:         if ($customer !== null) {
109:             // استخدامات العميل المسجل — الطلبات الملغاة لا تحتسب
110:             $usedByCustomer = $coupon->usages()
111:                 ->where('customer_id', $customer->id)
112:                 ->whereHas('order', fn ($q) => $q->where('status', '!=', OrderStatus::Cancelled->value))
113:                 ->count();
114:             if ($usedByCustomer >= (int) $coupon->usage_limit_per_customer) {
115:                 throw new BusinessException('وصلت لحد استخدام هذا الكوبون لحسابك.');
116:             }
117:         } elseif ($guestPhone !== null && trim($guestPhone) !== '') {
