119:             // مُتحققة لا يستنزف حد الحملة الكلي بطلبات وهمية بلا حدود —
120:             // الاستخدامات المعلّقة تُحسم بانتهاء صلاحية الطلب فيُلغى
121:             // ويُعكس الاستخدام (F-01 + M13)
122:             $pendingCap = (int) config('store.guest_coupon_pending_cap', 20);
123:             if ($pendingCap > 0) {
124:                 $pendingGuestUsages = $coupon->usages()
125:                     ->whereNotNull('guest_phone_normalized')
126:                     ->whereHas('order', fn ($q) => $q->where('status', OrderStatus::Pending->value))
127:                     ->count();
128:                 if ($pendingGuestUsages >= $pendingCap) {
129:                     throw new BusinessException('وصل هذا الكوبون لحد الطلبات المعلقة من الزوار؛ حاول لاحقًا.');
130:                 }
131:             }
132:             // هوية الزائر هي رقم هاتفه الموحد الصيغة — تبديل cart_token لا
133:             // يتجاوز الحد (H3). العدّ في SQL على العمود المفهرس (F-04)
134:             // بدل مسح كل الاستخدامات أثناء إمساك قفل الكوبون
135:             $usedByPhone = $coupon->usages()
136:                 ->where('guest_phone_normalized', Customer::normalizePhone($guestPhone))
137:                 ->whereHas('order', fn ($q) => $q->where('status', '!=', OrderStatus::Cancelled->value))
138:                 ->count();
139:             if ($usedByPhone >= (int) $coupon->usage_limit_per_customer) {
140:                 throw new BusinessException('وصلت لحد استخدام هذا الكوبون لرقم هاتفك.');
141:             }
142:         }
143:     }
