 20:  */
 21: class PaymentWebhookService
 22: {
 23:     private const SUCCESS = ['paid', 'success', 'successful', 'succeeded', 'captured', 'completed', 'approved'];
 24: 
 25:     private const FAILED = ['failed', 'voided', 'declined', 'error', 'cancelled', 'canceled'];
 26: 
 27:     public function __construct(
 28:         protected WebhookSignatureVerifier $verifier,
 29:         protected OrderService $orders,
 30:     ) {}
 31: 
 32:     /**
 33:      * @param  array<string, string|null>  $headers
 34:      * @param  array<string, mixed>  $query
 35:      * @return array{http: int, body: array<string, mixed>}
 36:      */
 37:     public function handle(string $gateway, array $payload, string $rawBody, array $headers, array $query, ?string $ip): array
 38:     {
 39:         $provider = 'payment:'.$gateway;
 40:         // قبل التحقق لا يُوثق بأي حقل من الحمولة (F-07): مفتاح السجل
 41:         // المختصر هو بصمة الجسم فقط، وأي معرّف من الحمولة قد يكون مصفوفة
 42:         // تكسر (string) أو نصًا أطول من عمود السجل فيحوّل الهجوم لـ 500
 43:         $preVerifyKey = 'sha256:'.hash('sha256', $rawBody);
 44: 
 45:         // حد حجم الجسم أولًا — الرفض بسجل مختصر بلا حمولة (M4)
 46:         if (strlen($rawBody) > 262144) {
 47:             $this->slimLog($provider, $preVerifyKey, 'rejected', 'payload too large', $ip);
 48: 
 49:             return ['http' => 413, 'body' => ['received' => false, 'message' => 'payload too large']];
 50:         }
 51: 
 52:         $config = config("webhooks.payment.{$gateway}");
 53:         if (! is_array($config)) {
 54:             $this->slimLog($provider, $preVerifyKey, 'failed', 'بوابة دفع غير معروفة', $ip);
 55: 
 56:             return ['http' => 404, 'body' => ['received' => false, 'message' => 'unknown gateway']];
 57:         }
 58: 
 59:         // التحقق بنمط البوابة (F-06) قبل تخزين الحمولة: محاولات مجهولة
 60:         // لا تملأ webhook_logs.payload — تُسجل مختصرة فقط (M4)
 61:         $verified = $this->verifier->verifyGateway(
 62:             (string) ($config['driver'] ?? 'hmac'),
 63:             $config['secret'] ?? null,
 64:             $rawBody,
 65:             $headers,
 66:             $query,
 67:             $payload,
 68:             $config['signature_header'] ?? null,
 69:         );
 70:         if (! $verified) {
 71:             $this->slimLog($provider, $preVerifyKey, 'invalid_signature', null, $ip);
 72: 
 73:             return ['http' => 403, 'body' => ['received' => false, 'message' => 'invalid signature']];
 74:         }
 75: 
 76:         // بعد التحقق فقط: معرّف الحدث من الحمولة مُنقّى (قيمة مفردة وحد
 77:         // طول) ومدموجًا بنتيجة الحدث (F-08) حتى لا يبتلع الاستردادَ حدثُ
 78:         // الدفعِ لنفس المعاملة فيُعلَّم duplicate
 79:         $outcome = $this->outcome($payload);
 80:         $extractedId = $this->extractEventId($payload);
 81:         $eventId = $extractedId !== null ? $extractedId.':'.$outcome : $preVerifyKey;
 82: 
 83:         $log = $this->startLog($provider, $eventId, $payload, $ip);
 84:         $log->update(['signature_valid' => true]);
 85: 
 86:         return DB::transaction(function () use ($gateway, $provider, $eventId, $payload, $log, $config, $outcome): array {
 87:             // قفل استشاري على مفتاح الحدث: نسختان متزامنتان من نفس الحدث تتسلسلان هنا
 88:             DB::statement('SELECT pg_advisory_xact_lock(hashtext(?))', [$provider.':'.$eventId]);
 89: 
 90:             if ($this->alreadyProcessed($provider, $log)) {
 91:                 $log->update(['status' => 'duplicate']);
 92: 
 93:                 return ['http' => 200, 'body' => ['received' => true, 'duplicate' => true]];
 94:             }
 95: 
 96:             $orderNumber = $this->extractOrderNumber($payload);
 97:             $order = $orderNumber !== null
 98:                 ? Order::query()->where('order_number', $orderNumber)->lockForUpdate()->first()
 99:                 : null;
100:             if ($order === null) {
101:                 $log->update(['status' => 'failed', 'error' => 'طلب غير موجود: '.($orderNumber ?? '—')]);
102: 
103:                 return ['http' => 200, 'body' => ['received' => false, 'message' => 'order not found']];
104:             }
105: 
106:             if ($outcome === 'ignored' || $outcome === 'pending') {
107:                 $log->update([
108:                     'status' => 'ignored',
109:                     'error' => $outcome === 'pending' ? 'معاملة معلقة لدى البوابة (pending)' : 'حالة دفع غير معروفة في الحمولة',
110:                 ]);
111: 
112:                 return ['http' => 200, 'body' => ['received' => true, 'ignored' => true]];
113:             }
114: 
115:             // التحقق من المبلغ والعملة قبل أي تغيير (H5)
116:             if ($outcome === 'paid' && ! $this->amountMatches($payload, $order, $config)) {
117:                 // المال قد يكون قُبض فعلًا مع مبلغ مخالف: يُعلَّم الطلب للانتباه
118:                 // ويُنبَّه السجل — لا يُكتفى بسجل failed صامت (F-22)
119:                 $order->update(['needs_attention' => true]);
120:                 $log->update(['status' => 'failed', 'error' => 'amount mismatch']);
121:                 Log::warning('Payment amount/currency mismatch on a paid event.', [
122:                     'order_id' => $order->id,
123:                     'order_number' => $order->order_number,
124:                     'gateway' => $gateway,
125:                     'expected' => (string) $order->grand_total,
126:                 ]);
127: 
128:                 return ['http' => 200, 'body' => ['received' => false, 'message' => 'amount mismatch']];
129:             }
130: 
131:             $note = null;
132:             if ($outcome === 'paid') {
133:                 if ($order->status === OrderStatus::Cancelled) {
134:                     // مال قُبض على طلب ملغي: يُثبت الدفع ويُعلَّم للاسترداد، ولا يُحيى الطلب
135:                     $order->update(['payment_status' => 'paid', 'requires_refund' => true]);
136:                     $note = 'دفع ناجح على طلب ملغي — يحتاج استردادًا';
137:                 } else {
138:                     $order->update(['payment_status' => 'paid']);
139:                     if ($order->status === OrderStatus::Pending) {
140:                         try {
141:                             $this->orders->changeStatus($order, OrderStatus::Confirmed, null, "تأكيد تلقائي بعد نجاح الدفع عبر {$gateway}");
142:                         } catch (Throwable $e) {
143:                             // «دُفع ولم يُؤكَّد» حالة تشغيلية خطيرة: تنبيه سجل +
144:                             // علامة ظاهرة في شاشة الطلب بدل دفنها في الويب هوك (M19)
145:                             Log::warning('Payment captured but order auto-confirm failed.', [
146:                                 'order_id' => $order->id,
147:                                 'order_number' => $order->order_number,
148:                                 'gateway' => $gateway,
149:                                 'exception' => $e->getMessage(),
150:                             ]);
151:                             $order->update(['needs_attention' => true]);
152:                             $note = 'تم الدفع لكن تأكيد الطلب فشل: '.$e->getMessage();
153:                         }
154:                     }
155:                 }
156:             } elseif ($outcome === 'failed') {
157:                 if ($order->payment_status === 'paid') {
158:                     // حدث فشل متأخر بعد نجاح: لا رجوع من paid إلى failed
159:                     $log->update(['status' => 'ignored', 'error' => 'حدث فشل متأخر بعد دفع ناجح — يُتجاهل']);
160: 
161:                     return ['http' => 200, 'body' => ['received' => true, 'ignored' => true]];
162:                 }
163:                 $order->update(['payment_status' => 'failed']);
164:             } else { // refunded
165:                 // الاسترداد لا يلغي الطلب لكنه يوقفه عن التنفيذ الصامت (F-05):
166:                 // علم انتباه لأي استرداد على طلب غير ملغي — وبوابة الشحن
167:                 // ترفض شحن دفع مسبق حالته ليست paid
168:                 $order->update([
169:                     'payment_status' => 'refunded',
170:                     'needs_attention' => $order->status !== OrderStatus::Cancelled,
171:                 ]);
172:                 Log::warning('Payment refunded for a non-cancelled order.', [
173:                     'order_number' => $order->order_number,
174:                     'gateway' => $gateway,
175:                 ]);
176:                 if (in_array($order->status, [OrderStatus::Shipped, OrderStatus::Delivered], true)) {
177:                     $note = 'استرداد على طلب مشحون/مُسلَّم — يحتاج مراجعة';
178:                 } else {
179:                     $note = 'تم استرداد الدفع — الطلب موسوم للانتباه ولن يخرج للشحن قبل مراجعة الدفع';
180:                 }
181:             }
182: 
183:             $log->update(['status' => 'processed', 'error' => $note]);
184: 
185:             return ['http' => 200, 'body' => ['received' => true]];
186:         });
187:     }
