189:     private function outcome(array $payload): string
190:     {
191:         // معاملة معلقة (Paymob: success=false مع pending=true) ليست فشلًا
192:         $pending = data_get($payload, 'obj.pending') ?? data_get($payload, 'data.pending') ?? data_get($payload, 'pending');
193:         if ($pending === true) {
194:             return 'pending';
195:         }
196: 
197:         $successFlag = data_get($payload, 'obj.success') ?? data_get($payload, 'data.success') ?? data_get($payload, 'success');
198:         if (is_bool($successFlag)) {
199:             return $successFlag ? 'paid' : 'failed';
200:         }
201: 
202:         $status = strtolower((string) ($this->firstValue($payload, ['status', 'payment_status', 'data.status', 'obj.status', 'state']) ?? ''));
203:         if (in_array($status, self::SUCCESS, true)) {
204:             return 'paid';
205:         }
206:         if ($status === 'refunded' || $status === 'refund') {
207:             return 'refunded';
208:         }
209:         if (in_array($status, self::FAILED, true)) {
210:             return 'failed';
211:         }
212: 
213:         return 'ignored';
214:     }
215: 
216:     /**
217:      * مقارنة مبلغ الحدث بإجمالي الطلب وعملته. إن لم يحمل الحدث مبلغًا
218:      * يُقبل (بعض البوابات لا ترسله) — وإن حمله واختلف يُرفض.
219:      *
220:      * @param  array<string, mixed>  $config
221:      */
222:     private function amountMatches(array $payload, Order $order, array $config): bool
223:     {
224:         $currency = $this->firstValue($payload, ['currency', 'data.currency', 'obj.currency', 'obj.order.currency']);
225:         if ($currency !== null && strtoupper((string) $currency) !== 'EGP') {
226:             return false;
227:         }
228: 
229:         $amount = $this->firstValue($payload, ['amount', 'data.amount', 'obj.amount', 'obj.order.amount']);
230:         $divisor = (float) ($config['amount_divisor'] ?? 1);
231:         if ($amount === null) {
232:             $cents = $this->firstValue($payload, ['amount_cents', 'data.amount_cents', 'obj.amount_cents', 'obj.order.amount_cents']);
233:             if ($cents !== null) {
234:                 $amount = $cents;
235:                 $divisor = 100.0;
236:             }
237:         }
238:         if ($amount === null) {
239:             return true;
240:         }
241: 
242:         return abs(round(((float) $amount) / $divisor, 2) - (float) $order->grand_total) < 0.01;
243:     }
244: 
245:     private function extractOrderNumber(array $payload): ?string
246:     {
247:         $value = $this->firstValue($payload, [
248:             'order_number', 'merchant_order_id', 'data.order_number',
249:             'obj.order.merchant_order_id', 'obj.merchant_order_id', 'metadata.order_number',
250:         ]);
251: 
252:         // قيم غير مفردة (مصفوفات) لا تُحوَّل لنص — تُتجاهل (F-07)
253:         return is_scalar($value) ? mb_substr((string) $value, 0, 191) : null;
254:     }
255: 
256:     private function extractEventId(array $payload): ?string
257:     {
258:         $value = $this->firstValue($payload, ['event_id', 'transaction_id', 'obj.id', 'data.id', 'data.transaction_id']);
259: 
260:         return is_scalar($value) ? mb_substr((string) $value, 0, 191) : null;
261:     }
262: 
263:     /** @param array<int, string> $keys */
264:     private function firstValue(array $payload, array $keys): mixed
265:     {
266:         foreach ($keys as $key) {
267:             $value = data_get($payload, $key);
268:             if ($value !== null && $value !== '') {
269:                 return $value;
270:             }
271:         }
272: 
273:         return null;
274:     }
