276:     private function startLog(string $provider, string $eventId, array $payload, ?string $ip): WebhookLog
277:     {
278:         return WebhookLog::create([
279:             'provider' => $provider,
280:             'event_id' => $eventId,
281:             'payload' => $payload,
282:             'status' => 'received',
283:             'ip_address' => $ip,
284:         ]);
285:     }
286: 
287:     /** سجل مختصر للطلبات المرفوضة قبل التحقق — بلا تخزين للحمولة (M4). */
288:     private function slimLog(string $provider, string $eventId, string $status, ?string $error, ?string $ip): void
289:     {
290:         WebhookLog::create([
291:             'provider' => $provider,
292:             'event_id' => $eventId,
293:             'payload' => null,
294:             'signature_valid' => false,
295:             'status' => $status,
296:             'error' => $error,
297:             'ip_address' => $ip,
298:         ]);
299:     }
300: 
301:     private function alreadyProcessed(string $provider, WebhookLog $current): bool
302:     {
303:         return WebhookLog::query()
304:             ->where('provider', $provider)
305:             ->where('event_id', $current->event_id)
306:             ->where('id', '!=', $current->id)
307:             ->where('status', 'processed')
308:             ->exists();
309:     }
