 78:         // سر التوقيع: webhook_secret الخاص بالشركة فقط — لا رجوع لمفتاح API
 79:         // ولا لسر افتراضي مشترك (M10)، والتحقق قبل تخزين الحمولة (M4)
 80:         $credentials = $company->api_credentials ?? [];
 81:         $secret = $credentials['webhook_secret'] ?? null;
 82:         if (! is_string($secret) || $secret === '' || ! $this->verifier->verify($secret, $rawBody, $signature)) {
 83:             $this->slimLog($provider, $preVerifyKey, 'invalid_signature',
 84:                 (! is_string($secret) || $secret === '') ? 'لا يوجد webhook_secret مضبوط للشركة' : null, $ip);
 85: 
 86:             return ['http' => 403, 'body' => ['received' => false, 'message' => 'invalid signature']];
 87:         }
 88: 
 89:         // بعد التحقق فقط يُشتق مفتاح الحدث من الحمولة (مُنقّى)
 90:         $eventId = $this->effectiveEventId($payload, $rawBody);
 91:         $log = $this->startLog($provider, $eventId, $payload, $ip);
 92:         $log->update(['signature_valid' => true]);
 93: 
 94:         return DB::transaction(function () use ($provider, $payload, $log, $company): array {
 95:             DB::statement('SELECT pg_advisory_xact_lock(hashtext(?))', [$provider.':'.$log->event_id]);
 96: 
 97:             if ($this->alreadyProcessed($provider, $log)) {
 98:                 $log->update(['status' => 'duplicate']);
 99: 
100:                 return ['http' => 200, 'body' => ['received' => true, 'duplicate' => true]];
101:             }
102: 
103:             $awb = $this->firstValue($payload, ['awb_number', 'tracking_number', 'awb', 'data.awb_number', 'data.tracking_number']);
104:             $shipment = $awb !== null
105:                 ? Shipment::query()->where('awb_number', (string) $awb)->where('shipping_company_id', $company->id)->lockForUpdate()->first()
106:                 : null;
107:             if ($shipment === null) {
108:                 $log->update(['status' => 'failed', 'error' => 'بوليصة غير موجودة: '.($awb !== null ? (string) $awb : '—')]);
109: 
110:                 return ['http' => 200, 'body' => ['received' => false, 'message' => 'shipment not found']];
111:             }
112: 
113:             $status = $this->mapStatus($payload);
114:             if ($status === null) {
115:                 $log->update(['status' => 'ignored', 'error' => 'حالة شحن غير معروفة في الحمولة']);
116: 
117:                 return ['http' => 200, 'body' => ['received' => true, 'ignored' => true]];
118:             }
119: 
120:             // ترتيب الحالات: لا تراجع من حالة نهائية ولا في سلسلة التقدم (H6)
121:             if (! $this->transitionAllowed($shipment->status, $status)) {
122:                 $log->update(['status' => 'ignored', 'error' => "حدث متأخر/متراجع: {$shipment->status->value} ← {$status->value}"]);
123: 
124:                 return ['http' => 200, 'body' => ['received' => true, 'ignored' => true]];
125:             }
126: 
127:             $shipment->update(['status' => $status]);
128: 
129:             $note = null;
130:             if ($status === ShipmentStatus::Returned) {
131:                 // إشعار المرتجع (بما فيه rto) يعني بدء الإرجاع لا وصوله:
132:                 // لا إعادة للمخزون من الويب هوك (F-15) — البضاعة قد تكون
133:                 // في الطريق أو تالفة. يُعلَّم الطلب للانتباه، والإعادة
134:                 // الفعلية عند استلام المستودع يدويًا (الأدمن → Returned
135:                 // عبر changeStatus فيسجل sale_return عندها فقط)
136:                 $order = $shipment->order;
137:                 if ($order !== null && in_array($order->status, [OrderStatus::Shipped, OrderStatus::Delivered], true)) {
138:                     $order->update(['needs_attention' => true]);
139:                     $note = 'أبلغت شركة الشحن بمرتجع — بانتظار استلام المستودع الفعلي قبل إعادة البضاعة للمخزون';
140:                 }
141:             }
142:             if ($status === ShipmentStatus::Failed) {
143:                 // بوليصة فاشلة لا تترك الطلب صامتًا (F-16): انتباه للمتابعة
