145:                 $order = $shipment->order;
146:                 if ($order !== null) {
147:                     $order->update(['needs_attention' => true]);
148:                     $note = 'فشلت البوليصة لدى شركة الشحن — يحتاج متابعة أو إصدار بوليصة بديلة';
149:                 }
