151:             if ($status === ShipmentStatus::Delivered) {
152:                 $order = $shipment->order;
153:                 if ($order !== null && $order->status === OrderStatus::Shipped) {
154:                     try {
155:                         // تسوية COD صارت أثرًا مركزيًا في changeStatus عند
156:                         // انتقال Delivered (F-14) — لا تكرار ولا تحصيل
157:                         // مُصنّع هنا: طلب غير مشحون لا ينتقل أصلًا
158:                         $this->orders->changeStatus($order, OrderStatus::Delivered, null, 'تم التسليم — إشعار شركة الشحن');
159:                     } catch (Throwable $e) {
160:                         $note = 'تم تسليم البوليصة لكن تحويل الطلب فشل: '.$e->getMessage();
161:                     }
162:                 }
163:             }
164: 
165:             $log->update(['status' => 'processed', 'error' => $note]);
166: 
167:             return ['http' => 200, 'body' => ['received' => true]];
168:         });
169:     }
