171:     private function transitionAllowed(ShipmentStatus $current, ShipmentStatus $new): bool
172:     {
173:         if ($current === $new) {
174:             return true;
175:         }
176:         // الحالات النهائية لا تتحرك
177:         if (in_array($current, [ShipmentStatus::Delivered, ShipmentStatus::Returned], true)) {
178:             return false;
179:         }
180:         // الفشل قد يحدث في أي مرحلة، ومن الفشل يمكن استئناف التقدم (إعادة محاولة التسليم)
181:         if ($new === ShipmentStatus::Failed || $current === ShipmentStatus::Failed) {
182:             return true;
183:         }
184:         // الإرجاع مسموح من أي مرحلة غير نهائية
185:         if ($new === ShipmentStatus::Returned) {
186:             return true;
187:         }
188: 
189:         return (self::RANK[$new->value] ?? 0) >= (self::RANK[$current->value] ?? 0);
190:     }
191: 
192:     /**
193:      * مفتاح حدث فعّال: معرّف حدث حقيقي فقط (id الشحنة ثابت في كل تحديثاتها
194:      * فلا يصلح مفتاحًا)، وإلا مركّب awb|status|timestamp، وإلا بصمة الجسم.
195:      */
196:     private function effectiveEventId(array $payload, string $rawBody): string
197:     {
198:         // كل قيمة تُستخدم في المفتاح يجب أن تكون مفردة وبحد طول (F-07)
199:         $eventId = $this->firstValue($payload, ['event_id', 'eventId', 'data.event_id']);
200:         if (is_scalar($eventId)) {
201:             return mb_substr((string) $eventId, 0, 191);
202:         }
203: 
204:         $awb = $this->firstValue($payload, ['awb_number', 'tracking_number', 'awb', 'data.awb_number']);
205:         $status = $this->firstValue($payload, ['status', 'state', 'shipment_status', 'data.status']);
206:         $timestamp = $this->firstValue($payload, ['timestamp', 'occurred_at', 'updated_at', 'data.timestamp', 'data.updated_at']);
207:         if (is_scalar($awb) && is_scalar($status) && is_scalar($timestamp)) {
208:             return mb_substr($awb.'|'.$status.'|'.$timestamp, 0, 191);
209:         }
210: 
211:         return 'sha256:'.hash('sha256', $rawBody);
212:     }
213: 
214:     private function mapStatus(array $payload): ?ShipmentStatus
215:     {
216:         $raw = $this->firstValue($payload, ['status', 'state', 'shipment_status', 'data.status', 'data.state']);
217:         if ($raw === null) {
218:             return null;
219:         }
220:         $key = str_replace([' ', '-'], '_', strtolower(trim((string) $raw)));
221: 
222:         return self::STATUS_MAP[$key] ?? null;
223:     }
224: 
225:     /** @param array<int, string> $keys */
226:     private function firstValue(array $payload, array $keys): mixed
227:     {
228:         foreach ($keys as $key) {
229:             $value = data_get($payload, $key);
230:             if ($value !== null && $value !== '') {
231:                 return $value;
232:             }
233:         }
234: 
235:         return null;
236:     }
