238:     private function startLog(string $provider, string $eventId, array $payload, ?string $ip): WebhookLog
239:     {
240:         return WebhookLog::create([
241:             'provider' => $provider,
242:             'event_id' => $eventId,
243:             'payload' => $payload,
244:             'status' => 'received',
245:             'ip_address' => $ip,
246:         ]);
247:     }
248: 
249:     /** سجل مختصر للطلبات المرفوضة قبل التحقق — بلا تخزين للحمولة (M4). */
250:     private function slimLog(string $provider, string $eventId, string $status, ?string $error, ?string $ip): void
251:     {
252:         WebhookLog::create([
253:             'provider' => $provider,
254:             'event_id' => $eventId,
255:             'payload' => null,
256:             'signature_valid' => false,
257:             'status' => $status,
258:             'error' => $error,
259:             'ip_address' => $ip,
260:         ]);
261:     }
262: 
263:     private function alreadyProcessed(string $provider, WebhookLog $current): bool
264:     {
265:         return WebhookLog::query()
266:             ->where('provider', $provider)
267:             ->where('event_id', $current->event_id)
268:             ->where('id', '!=', $current->id)
269:             ->where('status', 'processed')
270:             ->exists();
271:     }
