255:     /**
256:      * بوابة الحالة الوحيدة. $expectedFrom (F-11): حالات مصدر يفترضها
257:      * المستدعي على نسخته غير المقفولة — تُفحص بعد إعادة القراءة بالقفل،
258:      * فسباق (عميل يلغي × أدمن يجهّز) لا يمر من فحص قديم.
259:      *
260:      * @param  array<int, OrderStatus>|null  $expectedFrom
261:      */
262:     public function changeStatus(Order $order, OrderStatus|string $toStatus, ?Model $actor = null, ?string $notes = null, ?array $expectedFrom = null): Order
263:     {
264:         $to = $toStatus instanceof OrderStatus ? $toStatus : OrderStatus::from($toStatus);
265: 
266:         return DB::transaction(function () use ($order, $to, $actor, $notes, $expectedFrom): Order {
267:             // إعادة قراءة الطلب بقفل صف: النسخة الممرَّرة قد تكون قديمة،
268:             // وكل الانتقالات على نفس الطلب يجب أن تتسلسل (C1)
269:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
270:             $from = $order->status;
271: 
272:             if ($expectedFrom !== null && ! in_array($from, $expectedFrom, true)) {
273:                 throw new BusinessException("تغيّرت حالة الطلب أثناء العملية (أصبحت {$from->value})؛ أعد المحاولة.");
274:             }
275: 
276:             if ($from === $to) {
277:                 return $order;
278:             }
279: 
280:             if (! in_array($to->value, self::TRANSITIONS[$from->value] ?? [], true)) {
281:                 throw new BusinessException("انتقال حالة غير مسموح: من ({$from->value}) إلى ({$to->value}).");
282:             }
283: 
284:             $actorId = $this->inventoryActorId($actor);
285: 
286:             // آثار المخزون بحسب الانتقال
287:             $extraNote = null;
288:             if ($to === OrderStatus::Shipped) {
289:                 $this->shipOrder($order, $actorId);
290:             } elseif ($to === OrderStatus::Cancelled
291:                 && in_array($from, [OrderStatus::Pending, OrderStatus::Confirmed, OrderStatus::Processing], true)) {
292:                 // الحجز صار من لحظة الإنشاء (F-01) فيُفك من Pending أيضًا
293:                 $this->releaseReservations($order, $actorId, 'إلغاء الطلب');
294:             } elseif ($to === OrderStatus::Returned
295:                 && in_array($from, [OrderStatus::Shipped, OrderStatus::Delivered], true)) {
296:                 // إعادة البضاعة المشحونة للمخزون بحركات sale_return (M13)
297:                 if (! $this->returnSalesToStock($order, $actorId)) {
298:                     $extraNote = 'لا توجد حركات بيع مسجلة؛ يتطلب المرتجع استلامًا يدويًا في المستودع.';
299:                 }
300:             }
301: 
302:             if ($to === OrderStatus::Cancelled) {
303:                 // عكس استخدام الكوبون حتى لا يُحرم العميل منه بإلغاء (M13)
304:                 $this->reverseCouponUsage($order);
305:                 if ($order->payment_status === 'paid') {
306:                     $order->update(['requires_refund' => true]);
307:                 }
308:             }
309: 
310:             // مرتجع لطلب مدفوع يحتاج استردادًا أيضًا، لا الإلغاء فقط (F-14)
311:             if ($to === OrderStatus::Returned && $order->payment_status === 'paid') {
312:                 $order->update(['requires_refund' => true]);
313:             }
314: 
315:             $order->update(['status' => $to]);
316: 
317:             // تسوية COD عند التسليم من أي مسار (أدمن يدوي أو ويب هوك) —
318:             // الأثر هنا في بوابة الحالة لا في ويب هوك الشحن فقط (F-14)
319:             if ($to === OrderStatus::Delivered
320:                 && $order->payment_method === 'cod'
321:                 && $order->payment_status !== 'paid') {
322:                 $order->update(['payment_status' => 'paid']);
323:             }
324: 
325:             // notes عمود varchar(500): ملاحظة الأدمن (حتى 500) مع الملحق قد
326:             // تتجاوزه فتنفجر بحركة إرجاع بلا حركات بيع — تُقصّ على 500 (F-28)
327:             $historyNotes = trim(($notes ?? '').($extraNote !== null ? ' — '.$extraNote : '')) ?: $notes;
328: 
329:             $order->statusHistories()->create([
330:                 'from_status' => $from,
331:                 'to_status' => $to,
332:                 'changed_by_type' => $actor?->getMorphClass(),
333:                 'changed_by_id' => $actor?->getKey(),
334:                 'notes' => $historyNotes !== null ? mb_substr($historyNotes, 0, 500) : null,
335:             ]);
336: 
337:             if ($to === OrderStatus::Confirmed && $order->allocated_branch_id === null) {
338:                 $this->allocationService->allocate($order, performedBy: $actorId);
339:             }
340: 
341:             return $order->fresh(['items', 'statusHistories']);
342:         });
343:     }
