345:     /**
346:      * الشحن: لكل حركة حجز — فك الحجز من reserved وخصم فعلي sale من on_hand
347:      * على نفس صف الرصيد، وزيادة عدّاد مبيعات المنتج.
348:      */
349:     private function shipOrder(Order $order, ?int $actorId): void
350:     {
351:         $reservations = $this->reserveMovements($order);
352:         if ($reservations->isEmpty()) {
353:             throw new BusinessException('لا توجد حجوزات مخزون لهذا الطلب؛ لا يمكن الشحن قبل التأكيد والتوزيع.');
354:         }
355: 
356:         foreach ($reservations as $movement) {
357:             $base = [
358:                 'product_variant_id' => $movement->product_variant_id,
359:                 'branch_id' => $movement->branch_id,
360:                 'location_id' => $movement->location_id,
361:                 'reference_type' => Order::class,
362:                 'reference_id' => $order->id,
363:                 'created_by' => $actorId,
364:             ];
365:             $this->inventoryService->recordMovement([...$base,
366:                 'type' => StockMovementType::ReleaseReserve,
367:                 'affected_bucket' => StockBucket::Reserved,
368:                 'quantity' => -1 * (float) $movement->quantity,
369:                 'notes' => "فك حجز عند شحن الطلب {$order->order_number}",
370:             ]);
371:             $this->inventoryService->recordMovement([...$base,
372:                 'type' => StockMovementType::Sale,
373:                 'affected_bucket' => StockBucket::OnHand,
374:                 'quantity' => -1 * (float) $movement->quantity,
375:                 'notes' => "بيع عند شحن الطلب {$order->order_number}",
376:             ]);
377:         }
378: 
379:         foreach ($order->items as $item) {
380:             $item->variant?->product?->increment('sales_count', (int) round((float) $item->qty));
381:         }
382:     }
383: 
384:     /** إلغاء طلب مُحجوز: فك كل حجوزاته فتعود الكميات متاحة للبيع. */
385:     private function releaseReservations(Order $order, ?int $actorId, string $reason): void
386:     {
387:         foreach ($this->reserveMovements($order) as $movement) {
388:             $this->inventoryService->recordMovement([
389:                 'product_variant_id' => $movement->product_variant_id,
390:                 'branch_id' => $movement->branch_id,
391:                 'location_id' => $movement->location_id,
392:                 'type' => StockMovementType::ReleaseReserve,
393:                 'affected_bucket' => StockBucket::Reserved,
394:                 'quantity' => -1 * (float) $movement->quantity,
395:                 'reference_type' => Order::class,
396:                 'reference_id' => $order->id,
397:                 'created_by' => $actorId,
398:                 'notes' => "{$reason} {$order->order_number}",
399:             ]);
400:         }
401:     }
402: 
403:     /**
404:      * إعادة بضاعة طلب مشحون/مُسلَّم إلى المخزون: لكل حركة بيع حركة
405:      * sale_return معاكسة على نفس الرصيد، وتنقيص عدّاد المبيعات (M13).
406:      * ترجع false إذا لم توجد حركات بيع (يحتاج استلامًا يدويًا).
407:      */
408:     private function returnSalesToStock(Order $order, ?int $actorId): bool
409:     {
410:         $sales = StockMovement::query()
411:             ->where('reference_type', $order->getMorphClass())
412:             ->where('reference_id', $order->id)
413:             ->where('type', StockMovementType::Sale)
414:             ->orderBy('id')
415:             ->get();
416:         if ($sales->isEmpty()) {
417:             return false;
418:         }
419: 
420:         foreach ($sales as $movement) {
421:             $this->inventoryService->recordMovement([
422:                 'product_variant_id' => $movement->product_variant_id,
423:                 'branch_id' => $movement->branch_id,
424:                 'location_id' => $movement->location_id,
425:                 'type' => StockMovementType::SaleReturn,
426:                 'affected_bucket' => StockBucket::OnHand,
427:                 'quantity' => -1 * (float) $movement->quantity,
428:                 'reference_type' => Order::class,
429:                 'reference_id' => $order->id,
430:                 'created_by' => $actorId,
431:                 'notes' => "مرتجع مبيعات للطلب {$order->order_number}",
432:             ]);
433:         }
434: 
435:         foreach ($order->items as $item) {
436:             $product = $item->variant?->product;
437:             if ($product !== null) {
438:                 $product->update(['sales_count' => max(0, (int) $product->sales_count - (int) round((float) $item->qty))]);
439:             }
440:         }
441: 
442:         return true;
443:     }
