445:     /** عكس تسجيل استخدام الكوبون عند إلغاء الطلب: حذف السجل وإنقاص العدّاد (M13). */
446:     private function reverseCouponUsage(Order $order): void
447:     {
448:         foreach (CouponUsage::query()->where('order_id', $order->id)->get() as $usage) {
449:             Coupon::query()->whereKey($usage->coupon_id)->where('used_count', '>', 0)->decrement('used_count');
450:             $usage->delete();
451:         }
452:     }
453: 
454:     /** حركات الحجز الأصلية للطلب من الدفتر (مصدر الحقيقة لمواضع الحجز ومواقعه). */
455:     private function reserveMovements(Order $order): Collection
456:     {
457:         return StockMovement::query()
458:             ->where('reference_type', $order->getMorphClass())
459:             ->where('reference_id', $order->id)
460:             ->where('type', StockMovementType::Reserve)
461:             ->orderBy('id')
462:             ->get();
463:     }
