465:     // التخزين على مستوى الـ instance لا static (F-27): في Octane/العمال
466:     // طويلة العمر كانت قيمة static تبقى عالقة بين الطلبات وبين الاختبارات
467:     private ?int $systemActorId = null;
468: 
469:     private bool $systemActorResolved = false;
470: 
471:     /**
472:      * منفّذ حركات المخزون: الموظف الفاعل نفسه؛ وعند غيابه (عميل/ويب هوك)
473:      * يُنسب التنفيذ لمستخدم النظام المخصص (M19) — لا لأول Super Admin،
474:      * حتى يبقى سجل التدقيق صادقًا. يُحسم مرة واحدة لكل نسخة خدمة.
475:      */
476:     private function inventoryActorId(?Model $actor): ?int
477:     {
478:         if ($actor instanceof User) {
479:             return (int) $actor->getKey();
480:         }
481: 
482:         if (! $this->systemActorResolved) {
483:             $this->systemActorResolved = true;
484:             $systemId = User::query()
485:                 ->where('email', (string) config('orders.system_user_email', 'system@alfarid.local'))
486:                 ->value('id');
487:             $this->systemActorId = $systemId !== null ? (int) $systemId : null;
488:         }
489:         if ($this->systemActorId !== null) {
490:             return $this->systemActorId;
491:         }
492: 
493:         // رجوع احتياطي إن لم تُزرع هجرة مستخدم النظام بعد
494:         $adminId = User::query()
495:             ->whereHas('roles', fn ($q) => $q->where('name', 'Super Admin'))
496:             ->orderBy('id')
497:             ->value('id');
498: 
499:         return $adminId !== null ? (int) $adminId : (auth()->user() instanceof User ? (int) auth()->id() : null);
500:     }
